insert into public.parts(id,section_id,name,display_order,metadata) values('acc30d55-7639-3440-ab2d-92d11a811f7b','2dd5a6ad-d4e5-5141-982e-22469816765f','Craft and Structure',11,'{"sat_official_domain":"craft_and_structure","content_revision":"original-2026-10-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3a0f2c34-eaba-2073-1da8-cbb97177ca82','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The new pedestrian bridge was designed to ______ strong winds. Before construction began, engineers tested scale models in a wind tunnel to make sure the structure would remain stable during the region''s frequent winter storms.","options":[{"id":"A","label":"predict"},{"id":"B","label":"generate"},{"id":"C","label":"withstand"},{"id":"D","label":"avoid"}]}'::jsonb,1,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3a0f2c34-eaba-2073-1da8-cbb97177ca82','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the engineers tested the bridge to make sure it would stay stable in storms, so it was designed to withstand, or resist, strong winds. Choice A is incorrect because a bridge cannot forecast weather. Choice B is incorrect because the bridge does not create wind. Choice D is incorrect because a fixed bridge cannot avoid the wind; the text describes it standing up to wind."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a1712cbb-c066-5b58-6f93-4329d4c7d574','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Although the novelist''s first two books sold poorly, her later works were ______ by critics, who praised their inventive structure and vivid characters. Several of those later novels are now taught in university courses.","options":[{"id":"A","label":"ignored"},{"id":"B","label":"acclaimed"},{"id":"C","label":"rejected"},{"id":"D","label":"summarized"}]}'::jsonb,2,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a1712cbb-c066-5b58-6f93-4329d4c7d574','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because critics \"praised\" the later works, and \"although\" signals a contrast with the poor sales of the early books. Choice A is incorrect because praising a work is the opposite of ignoring it. Choice C is incorrect because rejecting conflicts with praise. Choice D is incorrect because summarizing is neutral and does not capture the praise the text describes."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('015f0fd5-84ac-fefb-0c51-d6c9b902c30c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"sound\" most nearly mean?","passage":"Before the town committee approved the plan for a new library, an independent engineer reviewed the budget and confirmed that its calculations were sound. With that assurance, the members voted unanimously to begin construction.","options":[{"id":"A","label":"reliable"},{"id":"B","label":"loud"},{"id":"C","label":"healthy"},{"id":"D","label":"musical"}]}'::jsonb,3,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('015f0fd5-84ac-fefb-0c51-d6c9b902c30c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the engineer''s review gave the committee \"assurance,\" which means the calculations were reliable, or free of errors. Choice B is incorrect because \"loud\" describes noise, not calculations. Choice C is incorrect because \"healthy\" applies to living things, as in \"a sound body,\" not to budgets. Choice D is incorrect because the text has nothing to do with music."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e54af03a-d01e-9d6b-de01-3063c55d0ae5','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Honeybees ______ information about food sources to other members of their hive through a series of movements known as the waggle dance. The angle and length of the dance indicate both the direction and the distance of the flowers.","options":[{"id":"A","label":"conceal"},{"id":"B","label":"invent"},{"id":"C","label":"forget"},{"id":"D","label":"communicate"}]}'::jsonb,4,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e54af03a-d01e-9d6b-de01-3063c55d0ae5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the dance indicates direction and distance to other bees, so it communicates information. Choice A is incorrect because the dance reveals, rather than hides, information. Choice B is incorrect because the bees report real locations rather than making information up. Choice C is incorrect because the bees convey information they have, not lose it."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('264149f5-034d-d056-eaf7-a540be3a0b5d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"address\" most nearly mean?","passage":"At the town meeting, the mayor promised to address residents'' concerns about traffic near the elementary school. She announced that the city would hire a crossing guard within the month and install a new crosswalk by the end of the year.","options":[{"id":"A","label":"give a speech to"},{"id":"B","label":"write a location on"},{"id":"C","label":"deal with"},{"id":"D","label":"ignore"}]}'::jsonb,5,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('264149f5-034d-d056-eaf7-a540be3a0b5d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the mayor follows her promise with concrete actions, a crossing guard and a crosswalk, which show she will deal with the concerns. Choice A is incorrect because one gives a speech to people, not to concerns, and the text emphasizes action rather than speaking. Choice B is incorrect because \"address\" in the sense of a mailing location does not fit concerns. Choice D is incorrect because the mayor is responding to the concerns, not ignoring them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1a843d4d-bf36-8da7-efe8-5d9d34854714','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The museum''s new exhibit is remarkably ______. It includes artifacts from six continents and spans more than three thousand years of history, from ancient pottery to twentieth-century photographs.","options":[{"id":"A","label":"wide-ranging"},{"id":"B","label":"temporary"},{"id":"C","label":"narrow"},{"id":"D","label":"expensive"}]}'::jsonb,6,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1a843d4d-bf36-8da7-efe8-5d9d34854714','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because artifacts from six continents covering three thousand years show that the exhibit covers a broad range. Choice B is incorrect because the text says nothing about how long the exhibit will last. Choice C is incorrect because \"narrow\" is the opposite of the breadth described. Choice D is incorrect because the text gives no information about cost."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('06d8bd36-e3df-d00f-b30b-717816db4174','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Because the hikers had only a ______ supply of water left, they decided to turn back before reaching the summit. Rather than risk running out on the steep trail, they agreed to try the climb again the following weekend.","options":[{"id":"A","label":"plentiful"},{"id":"B","label":"fresh"},{"id":"C","label":"shared"},{"id":"D","label":"limited"}]}'::jsonb,7,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('06d8bd36-e3df-d00f-b30b-717816db4174','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the hikers turned back to avoid running out of water, which makes sense only if their supply was limited. Choice A is incorrect because a plentiful supply would give them no reason to turn back. Choice B is incorrect because freshness does not explain the fear of running out. Choice C is incorrect because sharing the supply does not explain the decision."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('46fb8928-05f1-669b-9ff8-1b55c715807f','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Volcanologists closely monitor small earthquakes beneath active volcanoes. A sudden increase in the frequency of these earthquakes can ______ an approaching eruption, giving nearby communities valuable time to evacuate.","options":[{"id":"A","label":"prevent"},{"id":"B","label":"signal"},{"id":"C","label":"resemble"},{"id":"D","label":"delay"}]}'::jsonb,8,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('46fb8928-05f1-669b-9ff8-1b55c715807f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the earthquakes give communities time to evacuate, so they serve as a signal, or warning sign, of an eruption. Choice A is incorrect because the earthquakes do not stop eruptions. Choice C is incorrect because earthquakes are not described as looking like eruptions. Choice D is incorrect because nothing suggests the earthquakes postpone eruptions."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4b887b46-b14b-28f4-80d7-55608f9cd6f3','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"fine\" most nearly mean?","passage":"The potter mixed her clay with a fine sand, so smooth that it felt almost like flour between her fingers. The sand helped the clay hold its shape as it dried and kept the finished bowls from cracking in the kiln.","options":[{"id":"A","label":"made of very small particles"},{"id":"B","label":"acceptable"},{"id":"C","label":"sunny"},{"id":"D","label":"excellent"}]}'::jsonb,9,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4b887b46-b14b-28f4-80d7-55608f9cd6f3','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the sand is compared to flour and described as smooth, which indicates tiny particles. Choice B is incorrect because \"fine\" in the sense of \"okay\" does not fit a description of texture. Choice C is incorrect because \"fine\" in the sense of good weather does not apply to sand. Choice D is incorrect because the text describes the sand''s texture, not its quality."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fffbaf19-2ef9-d2d7-523d-c565762ead2e','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The historian''s account of the strike is thoroughly ______. She supports nearly every claim with evidence from letters, diaries, newspaper reports, and official records of the period.","options":[{"id":"A","label":"speculative"},{"id":"B","label":"documented"},{"id":"C","label":"brief"},{"id":"D","label":"fictional"}]}'::jsonb,10,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fffbaf19-2ef9-d2d7-523d-c565762ead2e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because supporting nearly every claim with records means the account is documented. Choice A is incorrect because speculation lacks the evidence the text describes. Choice C is incorrect because the text says nothing about length. Choice D is incorrect because an account built on historical records is not fictional."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3ddaaf81-e13a-1603-65b0-b172b8e46ce5','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The chef''s most famous dish is surprisingly ______. It contains only three ingredients and takes about ten minutes to cook, yet diners often assume that it must have taken hours to prepare.","options":[{"id":"A","label":"elaborate"},{"id":"B","label":"costly"},{"id":"C","label":"spicy"},{"id":"D","label":"simple"}]}'::jsonb,11,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3ddaaf81-e13a-1603-65b0-b172b8e46ce5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because a dish with only three ingredients is simple, and \"surprisingly\" and \"yet\" contrast that simplicity with diners'' assumptions. Choice A is incorrect because \"elaborate\" is what diners wrongly assume, not what the dish is. Choice B is incorrect because cost is never mentioned. Choice C is incorrect because flavor is not discussed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f4820bad-5004-7d18-2188-72a5916c49c0','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"For many years, scientists ______ that the deep ocean floor was nearly lifeless, since little sunlight reaches it. Expeditions in the 1970s, however, discovered thriving communities of animals living around hot springs on the seafloor.","options":[{"id":"A","label":"proved"},{"id":"B","label":"denied"},{"id":"C","label":"assumed"},{"id":"D","label":"forgot"}]}'::jsonb,12,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f4820bad-5004-7d18-2188-72a5916c49c0','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the belief turned out to be wrong, which fits an assumption rather than something established. Choice A is incorrect because a belief later shown to be false had not been proved. Choice B is incorrect because \"however\" signals that the discovery contradicted the scientists'' view, so they must have held it rather than denied it. Choice D is incorrect because \"For many years\" and \"however\" show that scientists actively held the belief until the discoveries contradicted it."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9bf617b6-4170-4cab-6439-b9282571d1fe','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"check\" most nearly mean?","passage":"To check the spread of an invasive vine, park staff cut it back every spring and planted native shrubs that compete with it for sunlight. After five years, the vine covered less than a third of the area it once did.","options":[{"id":"A","label":"inspect"},{"id":"B","label":"mark"},{"id":"C","label":"pay for"},{"id":"D","label":"restrain"}]}'::jsonb,13,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9bf617b6-4170-4cab-6439-b9282571d1fe','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because cutting the vine and planting competitors reduced its coverage, so the staff were restraining its spread. Choice A is incorrect because the staff did more than look at the vine; they acted to limit it. Choice B is incorrect because \"mark,\" as in a check mark, does not fit the context. Choice C is incorrect because the text has nothing to do with payment."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9c79784b-4cc0-48e7-db0b-050d6daa38fd','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Residents were ______ about the proposed factory. Some welcomed the jobs it would bring to the town, while others worried that it would pollute the river that supplies their drinking water.","options":[{"id":"A","label":"divided"},{"id":"B","label":"unanimous"},{"id":"C","label":"uninformed"},{"id":"D","label":"enthusiastic"}]}'::jsonb,14,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9c79784b-4cc0-48e7-db0b-050d6daa38fd','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because some residents supported the factory and others opposed it, so opinion was divided. Choice B is incorrect because residents did not all agree. Choice C is incorrect because residents had specific reasons for their views, showing they were informed. Choice D is incorrect because only some residents were positive."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('de093a33-8345-17c4-f79b-979a27da21d1','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Although the treaty was celebrated at the time as a turning point, historians note that its effects were largely ______. Most of its provisions were never enforced, and the border disputes it was meant to settle continued for decades.","options":[{"id":"A","label":"immediate"},{"id":"B","label":"practical"},{"id":"C","label":"symbolic"},{"id":"D","label":"permanent"}]}'::jsonb,15,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('de093a33-8345-17c4-f79b-979a27da21d1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because a treaty that was celebrated but whose provisions were never enforced mattered more as a symbol than in practice. Choice A is incorrect because the disputes continued for decades. Choice B is incorrect because the treaty''s provisions had little practical effect. Choice D is incorrect because nothing about the effects lasted in the way \"permanent\" implies."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5d19fecf-6c48-877a-ce72-54d69ce9506a','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"arrested\" most nearly mean?","passage":"The introduction of a new antibiotic arrested the spread of the infection through the hospital ward. Within a week of the first doses, no new cases were reported, and most patients had begun to recover.","options":[{"id":"A","label":"captured"},{"id":"B","label":"stopped"},{"id":"C","label":"attracted"},{"id":"D","label":"accused"}]}'::jsonb,16,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5d19fecf-6c48-877a-ce72-54d69ce9506a','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because no new cases appeared after the antibiotic was introduced, meaning the spread was stopped. Choice A is incorrect because \"captured\" suggests a police arrest, which does not apply to an infection''s spread. Choice C is incorrect because \"arrested\" here does not mean drawing attention, as in an \"arresting\" image. Choice D is incorrect because nothing is being charged with wrongdoing."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ff9bd013-087d-1323-2761-412067bc33ba','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The scientist was careful not to ______ her results. In interviews, she described the drug''s effects as \"promising in early trials\" rather than calling it a cure, and she stressed that larger studies were still needed.","options":[{"id":"A","label":"overstate"},{"id":"B","label":"publish"},{"id":"C","label":"dispute"},{"id":"D","label":"understand"}]}'::jsonb,17,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ff9bd013-087d-1323-2761-412067bc33ba','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because her cautious wording and insistence on larger studies show she avoided exaggerating her results. Choice B is incorrect because she discussed the results publicly in interviews. Choice C is incorrect because she did not question her own findings; she simply described them modestly. Choice D is incorrect because her precise description shows that she understood her results."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a003982c-5954-63cb-91e4-176764f0a459','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"appreciate\" most nearly mean?","passage":"Investors who bought land along the planned route of the railroad in the 1860s often saw its value appreciate rapidly once trains began running. Towns grew up around the new stations, and plots that had once sold cheaply became prized locations for shops and hotels.","options":[{"id":"A","label":"recognize"},{"id":"B","label":"increase"},{"id":"C","label":"enjoy"},{"id":"D","label":"thank"}]}'::jsonb,18,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a003982c-5954-63cb-91e4-176764f0a459','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because cheap plots became prized locations, so the land''s value increased. Choice A is incorrect because value cannot \"recognize\" anything; that sense applies to people. Choice C is incorrect because \"enjoy\" also applies to people, not to value. Choice D is incorrect because \"thank\" is a sense of \"appreciate\" that does not fit a property''s worth."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fc80513f-3477-da41-4a64-08593d4ce87b','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"incredulity\" most nearly mean?","passage":"Adapted from Charles Dickens, A Tale of Two Cities, 1859.\n\nIt was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity, it was the season of Light, it was the season of Darkness.","options":[{"id":"A","label":"astonishment"},{"id":"B","label":"ignorance"},{"id":"C","label":"disbelief"},{"id":"D","label":"dishonesty"}]}'::jsonb,19,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fc80513f-3477-da41-4a64-08593d4ce87b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the sentence pairs opposites (best and worst, wisdom and foolishness), so \"incredulity\" is set against \"belief\" and means disbelief. Choice A is incorrect because astonishment is surprise, not the opposite of belief. Choice B is incorrect because \"incredulity\" is set against \"belief,\" and ignorance is a lack of knowledge, not a refusal to believe. Choice D is incorrect because dishonesty concerns lying, not a refusal to believe."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('63258bfb-61ef-6fbf-ce7d-67de26b210be','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Rather than ______ the two competing theories, the researcher proposed a new model that combined elements of both. Each theory, she argued, correctly explained part of the data but failed to account for the rest.","options":[{"id":"A","label":"combining"},{"id":"B","label":"describing"},{"id":"C","label":"testing"},{"id":"D","label":"choosing between"}]}'::jsonb,20,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('63258bfb-61ef-6fbf-ce7d-67de26b210be','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because \"rather than\" sets up a contrast with combining both theories, and the natural contrast is picking one over the other. Choice A is incorrect because combining is what the researcher did, so it cannot be what she did instead. Choice B is incorrect because describing the theories is not an alternative to combining them; she evidently described them in making her argument. Choice C is incorrect because her argument depends on how each theory fits the data, so she did not avoid testing them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8cc4009a-e9a1-d6e4-2fd7-cb62431cec10','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"conservative\" most nearly mean?","passage":"The engineers'' estimate of the bridge''s capacity was deliberately conservative. They calculated the maximum load the structure could bear and then posted a limit well below it, so that the bridge would remain safe even if their assumptions proved slightly wrong.","options":[{"id":"A","label":"cautious"},{"id":"B","label":"traditional"},{"id":"C","label":"political"},{"id":"D","label":"plain"}]}'::jsonb,21,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8cc4009a-e9a1-d6e4-2fd7-cb62431cec10','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because setting a limit well below the calculated maximum to allow for error is cautious. Choice B is incorrect because the text concerns a safety margin, not respect for tradition. Choice C is incorrect because the text is not about politics. Choice D is incorrect because \"conservative\" in the sense of plain style, such as clothing, does not fit an estimate."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e111893a-baaf-656d-e841-18c93c95c8bf','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Field biologists rarely observe the elusive snow leopard directly. Instead, they ______ its presence from indirect evidence, such as tracks in the snow, scat, and images captured by motion-activated cameras.","options":[{"id":"A","label":"deny"},{"id":"B","label":"conceal"},{"id":"C","label":"infer"},{"id":"D","label":"announce"}]}'::jsonb,22,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e111893a-baaf-656d-e841-18c93c95c8bf','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because biologists draw conclusions about the leopard from indirect signs, which is what it means to infer. Choice A is incorrect because the evidence indicates the leopard is present. Choice B is incorrect because biologists are gathering, not hiding, evidence. Choice D is incorrect because announcing does not describe working from indirect evidence."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f6d90e14-b691-4cf6-8a73-74a3921b79a3','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"compromised\" most nearly mean?","passage":"The blood sample had been left at room temperature for several days before it reached the laboratory. Worried that its integrity was compromised, the researchers discarded it and repeated the test with a fresh sample.","options":[{"id":"A","label":"negotiated"},{"id":"B","label":"damaged"},{"id":"C","label":"disclosed"},{"id":"D","label":"agreed upon"}]}'::jsonb,23,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f6d90e14-b691-4cf6-8a73-74a3921b79a3','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the researchers discarded the sample, which makes sense only if they thought it had been damaged by poor storage. Choice A is incorrect because \"negotiated\" reflects the meaning of reaching a compromise, which does not fit a sample. Choice C is incorrect because nothing about the sample was revealed to outsiders, as in a \"compromised password\"; the problem is its physical condition. Choice D is incorrect because nothing about the sample was agreed upon."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('275bbb88-64e3-a3a6-e6ae-e4d8298d4b25','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The poet''s late work is notably ______. Where her early poems sprawled across several pages in long, winding sentences, the later poems rarely run longer than a dozen short lines.","options":[{"id":"A","label":"verbose"},{"id":"B","label":"mournful"},{"id":"C","label":"rhythmic"},{"id":"D","label":"concise"}]}'::jsonb,24,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('275bbb88-64e3-a3a6-e6ae-e4d8298d4b25','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the later poems are contrasted with sprawling early work and are only a dozen short lines, so they are concise. Choice A is incorrect because \"verbose\" describes the early poems, not the late ones. Choice B is incorrect because the text discusses length, not mood. Choice C is incorrect because the text says nothing about rhythm."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c1097ec1-817b-1488-e475-62dd0cb033e4','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"realized\" most nearly mean?","passage":"After years of saving, the couple finally realized their plan of opening a small bakery on the corner of their street. The shop welcomed its first customers in the spring and has sold out of bread nearly every morning since.","options":[{"id":"A","label":"understood"},{"id":"B","label":"achieved"},{"id":"C","label":"noticed"},{"id":"D","label":"imagined"}]}'::jsonb,25,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c1097ec1-817b-1488-e475-62dd0cb033e4','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the bakery actually opened, meaning the couple achieved their plan. Choice A is incorrect because the text describes carrying out the plan, not understanding it. Choice C is incorrect because one does not merely notice a plan one has worked years to fulfill. Choice D is incorrect because the plan became real, so it was more than imagined."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f8519932-9451-f828-d23d-a6134043ed3f','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Many scientists initially greeted the claim with ______, since it contradicted decades of careful observations. Only after several independent laboratories reproduced the results did the finding gain wide acceptance.","options":[{"id":"A","label":"enthusiasm"},{"id":"B","label":"indifference"},{"id":"C","label":"skepticism"},{"id":"D","label":"gratitude"}]}'::jsonb,26,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f8519932-9451-f828-d23d-a6134043ed3f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because a claim that contradicted long-standing evidence and needed independent confirmation before being accepted would first be met with doubt. Choice A is incorrect because enthusiasm would not require confirmation before acceptance. Choice B is incorrect because scientists cared enough to reproduce the results. Choice D is incorrect because nothing suggests scientists were thankful for a claim they doubted."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21315521-01e1-ddc3-f90c-42e4594fb85e','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"account\" most nearly mean?","passage":"Adapted from Herman Melville, Moby-Dick, 1851.\n\nWhenever I find myself growing grim about the mouth; whenever it is a damp, drizzly November in my soul; whenever I find myself involuntarily pausing before coffin warehouses, and bringing up the rear of every funeral I meet . . . then, I account it high time to get to sea as soon as I can.","options":[{"id":"A","label":"consider"},{"id":"B","label":"report"},{"id":"C","label":"charge"},{"id":"D","label":"explain"}]}'::jsonb,27,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('21315521-01e1-ddc3-f90c-42e4594fb85e','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the narrator judges, or considers, it high time to go to sea when he feels gloomy. Choice B is incorrect because he is not giving a report of events. Choice C is incorrect because \"account\" in a financial sense does not fit. Choice D is incorrect because he is not explaining the time; he is judging that the moment has come."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ffb16ea3-db44-210d-a36a-b4a49f9efaaa','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Researchers hoping to trace the town''s history quickly discovered that its archive is far from ______. Records from several decades were lost in a fire, and many of the surviving files are missing pages.","options":[{"id":"A","label":"damaged"},{"id":"B","label":"accessible"},{"id":"C","label":"organized"},{"id":"D","label":"complete"}]}'::jsonb,28,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ffb16ea3-db44-210d-a36a-b4a49f9efaaa','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because lost records and missing pages show the archive is far from complete. Choice A is incorrect because the archive clearly is damaged, so \"far from damaged\" contradicts the text. Choice B is incorrect because the researchers are using the archive, and the problems described concern missing material, not access. Choice C is incorrect because the problems described involve lost material, not arrangement."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dae6287c-f08b-3a6f-2f4c-55657091d607','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"cultivate\" most nearly mean?","passage":"Early in her career, the diplomat worked to cultivate relationships with officials in neighboring countries. She met with them regularly for years, long before any crisis required their cooperation, so that trust would already exist when it was needed.","options":[{"id":"A","label":"develop"},{"id":"B","label":"farm"},{"id":"C","label":"cut short"},{"id":"D","label":"study"}]}'::jsonb,29,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('dae6287c-f08b-3a6f-2f4c-55657091d607','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because meeting regularly for years to build trust is developing relationships. Choice B is incorrect because the literal agricultural sense of \"cultivate\" does not apply to relationships. Choice C is incorrect because she sustained the relationships rather than ending them. Choice D is incorrect because she was building relationships, not analyzing them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9037946f-2a4d-ab52-ba9e-0bf9bb4c627c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Although the two species of tree frog look nearly identical, their calls are clearly ______. One produces a rapid, high-pitched trill, while the other gives a series of slow, low croaks.","options":[{"id":"A","label":"similar"},{"id":"B","label":"distinct"},{"id":"C","label":"silent"},{"id":"D","label":"rare"}]}'::jsonb,30,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9037946f-2a4d-ab52-ba9e-0bf9bb4c627c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because \"although\" contrasts the frogs'' similar appearance with their calls, which the text shows are very different. Choice A is incorrect because it removes the contrast and contradicts the different calls described. Choice C is incorrect because the frogs clearly make sounds. Choice D is incorrect because the text describes what the calls sound like, not how often they occur."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ca5815d5-7a44-49f1-3b15-62497734762d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The economist''s argument is not that tariffs are always harmful but that their net benefits are routinely ______. Proponents, she contends, tally the jobs a tariff protects while overlooking the costs it imposes on the many industries that depend on imported materials.","options":[{"id":"A","label":"ignored"},{"id":"B","label":"underestimated"},{"id":"C","label":"distributed"},{"id":"D","label":"overstated"}]}'::jsonb,31,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ca5815d5-7a44-49f1-3b15-62497734762d','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because proponents count the benefits while leaving out the costs, so the net benefit is made to look larger than it is. Choice A is incorrect because proponents do count the benefits; it is the costs they overlook. Choice B is incorrect because it reverses the economist''s point. Choice C is incorrect because the passage concerns how benefits are counted, not how they are shared."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2452c91c-35bf-d8fc-4fec-3e11c3e08d5f','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"qualified\" most nearly mean?","passage":"The reviewer offered only qualified praise for the new biography. She admired the depth of its archival research but faulted its persistent tendency to excuse its subject''s failures and to blame them on others.","options":[{"id":"A","label":"competent"},{"id":"B","label":"certified"},{"id":"C","label":"limited"},{"id":"D","label":"enthusiastic"}]}'::jsonb,32,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2452c91c-35bf-d8fc-4fec-3e11c3e08d5f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the reviewer''s praise for the research is accompanied by criticism, so the praise is limited, or restricted. Choice A is incorrect because \"competent\" applies to a person''s ability, not to praise. Choice B is incorrect because \"certified\" refers to official credentials. Choice D is incorrect because praise mixed with criticism is not wholehearted."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('83971607-405c-522b-fcf4-37ab7eaeb2e1','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Far from being ______, the theory''s central claim has been revised repeatedly as new fossils have come to light. Its proponents describe it less as a settled conclusion than as a working framework that will continue to change.","options":[{"id":"A","label":"immutable"},{"id":"B","label":"tentative"},{"id":"C","label":"obscure"},{"id":"D","label":"popular"}]}'::jsonb,33,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('83971607-405c-522b-fcf4-37ab7eaeb2e1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because \"far from\" introduces the opposite of what follows, and a claim revised repeatedly is the opposite of unchangeable. Choice B is incorrect because a working framework that keeps changing is tentative, so \"far from tentative\" contradicts the text. Choice C is incorrect because the text does not discuss how well known the theory is. Choice D is incorrect because popularity has no relationship to repeated revision."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('da66855e-3051-2774-53de-160934bcb697','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"betrayed\" most nearly mean?","passage":"Though the diplomat spoke calmly throughout the negotiation, his repeated glances at the clock betrayed an impatience he was otherwise careful to conceal. By the final hour, even his counterparts had noticed it.","options":[{"id":"A","label":"deceived"},{"id":"B","label":"abandoned"},{"id":"C","label":"resisted"},{"id":"D","label":"revealed"}]}'::jsonb,34,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('da66855e-3051-2774-53de-160934bcb697','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because his glances exposed the impatience he tried to hide, and the others noticed it. Choice A is incorrect because the glances did not mislead anyone; they made his feelings plain. Choice B is incorrect because \"abandoned,\" as in betraying a friend, does not fit an emotion being shown. Choice C is incorrect because the glances expressed rather than resisted his impatience."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('850a053f-b963-f97c-a6f9-5e7d6b308118','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The surviving record of the colony''s first winter is strikingly ______. Settlers'' letters describe a famine in vivid detail, yet the official ledgers kept during the same months record ordinary harvests and no unusual deaths.","options":[{"id":"A","label":"sparse"},{"id":"B","label":"contradictory"},{"id":"C","label":"consistent"},{"id":"D","label":"fabricated"}]}'::jsonb,35,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('850a053f-b963-f97c-a6f9-5e7d6b308118','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the letters and ledgers give incompatible accounts of the same period. Choice A is incorrect because the record includes detailed letters and ledgers, so it is not sparse. Choice C is incorrect because the sources disagree. Choice D is incorrect because the text shows a conflict between sources but does not establish that either was invented."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d943d2c4-a0cc-972e-2bff-4fd1c8091224','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"tempered\" most nearly mean?","passage":"Her optimism about the new treatment was tempered by the knowledge that earlier drugs had shown similar promise in small trials before failing in larger studies. She would wait, she said, for results from a trial involving thousands of patients.","options":[{"id":"A","label":"hardened"},{"id":"B","label":"angered"},{"id":"C","label":"moderated"},{"id":"D","label":"delayed"}]}'::jsonb,36,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-036","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d943d2c4-a0cc-972e-2bff-4fd1c8091224','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because knowing that earlier drugs failed made her optimism more restrained, which is why she would wait for larger results. Choice A is incorrect because \"hardened,\" as in tempered steel, would suggest her optimism grew firmer, the opposite of what happened. Choice B is incorrect because \"temper\" in the sense of anger does not fit. Choice D is incorrect because her optimism was reduced in degree, not postponed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f030adba-51c6-2c8b-b401-aa4f02b796fe','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"The committee''s report was notably ______ in its criticism. Rather than condemning the agency outright, it noted \"areas where further attention may be warranted,\" wording that several members later admitted had been chosen to avoid giving offense.","options":[{"id":"A","label":"scathing"},{"id":"B","label":"inconsistent"},{"id":"C","label":"measured"},{"id":"D","label":"premature"}]}'::jsonb,37,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-037","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f030adba-51c6-2c8b-b401-aa4f02b796fe','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the report avoided outright condemnation and used deliberately mild language, so its criticism was measured, or restrained. Choice A is incorrect because \"scathing\" means harshly critical, the opposite of the mild wording described. Choice B is incorrect because the report used one careful tone; no inconsistency is described. Choice D is incorrect because nothing suggests the report came too early."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8ecfafdb-f70a-7aa2-5f78-d42afecade65','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"discharge\" most nearly mean?","passage":"Having been asked to discharge the duties of the absent treasurer, the vice president spent the spring reconciling the society''s accounts and preparing its annual budget. Members later praised the care with which she had handled the unfamiliar work.","options":[{"id":"A","label":"release"},{"id":"B","label":"carry out"},{"id":"C","label":"dismiss"},{"id":"D","label":"unload"}]}'::jsonb,38,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-038","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8ecfafdb-f70a-7aa2-5f78-d42afecade65','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the vice president performed the treasurer''s tasks, reconciling accounts and preparing a budget, which is carrying out duties. Choice A is incorrect because she did not free herself from the duties; she performed them. Choice C is incorrect because no one was dismissed from a position. Choice D is incorrect because the literal sense of unloading cargo does not fit duties she performed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7db83596-aa7b-4d5d-e7cf-a86d1de8a991','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice completes the text with the most logical and precise word or phrase?","passage":"Some historians regard the reform as ______. By granting modest concessions, they argue, it relieved public pressure for the broader changes that activists had demanded, so that the reform''s apparent success actually helped forestall more substantial change.","options":[{"id":"A","label":"preemptive"},{"id":"B","label":"transformative"},{"id":"C","label":"unprecedented"},{"id":"D","label":"accidental"}]}'::jsonb,39,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-039","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7db83596-aa7b-4d5d-e7cf-a86d1de8a991','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the historians describe a reform that offered small concessions to head off larger changes before they could happen, which is what \"preemptive\" means. Choice B is incorrect because modest concessions that blocked broader change were not transformative. Choice C is incorrect because the text does not say whether anything like the reform had happened before. Choice D is incorrect because the historians present the reform as having this effect, not as arising by chance."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('72a2217e-6750-b73d-8cf1-bc25a5bc0fc0','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"As used in the text, what does the word \"Admit\" most nearly mean?","passage":"Adapted from William Shakespeare, Sonnet 116, 1609.\n\nLet me not to the marriage of true minds\nAdmit impediments. Love is not love\nWhich alters when it alteration finds,\nOr bends with the remover to remove:\nO no! it is an ever-fixed mark\nThat looks on tempests and is never shaken.","options":[{"id":"A","label":"hold"},{"id":"B","label":"enroll"},{"id":"C","label":"enter"},{"id":"D","label":"allow"}]}'::jsonb,40,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"words_in_context","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-wic-040","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('72a2217e-6750-b73d-8cf1-bc25a5bc0fc0','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the speaker refuses to allow that obstacles could stand in the way of true love, which he goes on to describe as fixed and unshaken. Choice A is incorrect because \"admit\" in the sense of having room for, as in \"the hall admits three hundred guests,\" does not fit obstacles to a marriage. Choice B is incorrect because nothing is being enrolled, as in admitting a student. Choice C is incorrect because \"admit\" means to let something in, not to go in oneself, and the speaker is not describing anything going in."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('672f5b04-2d8c-71f2-45e6-584e20f5afd0','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Sea turtles spend most of their lives at sea, but females return to land to lay their eggs. Many return to the same stretch of beach where they themselves hatched, sometimes after traveling thousands of kilometers. Scientists think the turtles find their way partly by sensing Earth''s magnetic field, which varies slightly from place to place along the coast.","options":[{"id":"A","label":"To argue that sea turtle nesting beaches should be protected from development"},{"id":"B","label":"To describe a behavior of sea turtles and a possible explanation for how they accomplish it"},{"id":"C","label":"To compare the navigation abilities of sea turtles with those of other migrating animals"},{"id":"D","label":"To explain why Earth''s magnetic field varies along coastlines"}]}'::jsonb,41,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('672f5b04-2d8c-71f2-45e6-584e20f5afd0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the text describes females returning to their birth beaches and then offers magnetic sensing as a possible explanation. Choice A is incorrect because the text makes no argument about protecting beaches. Choice C is incorrect because no other animals are discussed. Choice D is incorrect because the text mentions the field''s variation only to explain the turtles'' navigation, not to explain the variation itself."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5042478c-cadc-11d2-bbf7-e1601f8759ef','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Many people assume that the tomato, first cultivated in the Americas, was eagerly embraced in Europe soon after explorers brought it back in the 1500s. In fact, many Europeans were initially wary of the plant, which belongs to the same family as several poisonous species, and grew it mainly as an ornamental curiosity. Only gradually, over the next two centuries, did tomatoes become a common ingredient in European cooking.","options":[{"id":"A","label":"It describes a scientific experiment and then reports its results."},{"id":"B","label":"It compares two plants and argues that one is more nutritious than the other."},{"id":"C","label":"It presents a common assumption, corrects it, and then describes what actually happened over time."},{"id":"D","label":"It lists several reasons why the tomato was popular in Europe from the start."}]}'::jsonb,42,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5042478c-cadc-11d2-bbf7-e1601f8759ef','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the text opens with what \"many people assume,\" says \"in fact\" Europeans were wary, and ends with the slow adoption of tomatoes in cooking. Choice A is incorrect because no experiment is described. Choice B is incorrect because nutrition is never discussed. Choice D is incorrect because the text says the tomato was not popular at first."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('80defa8a-9f12-5a34-7f8c-040820164459','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Every autumn, the town of Ashby holds a three-day festival celebrating its apple orchards. Visitors can tour the orchards, press their own cider, and sample dozens of apple varieties. <u>This year, however, a late spring frost destroyed much of the blossom, and organizers announced that the festival would be shortened to a single day.</u>","options":[{"id":"A","label":"It provides another example of an activity that visitors can enjoy."},{"id":"B","label":"It introduces the history of the town''s orchards."},{"id":"C","label":"It argues that the festival should be canceled permanently."},{"id":"D","label":"It explains a change to the usual event described in the previous sentences."}]}'::jsonb,43,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('80defa8a-9f12-5a34-7f8c-040820164459','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because \"however\" signals that this year differs from the usual three-day festival, and the sentence explains why it was shortened. Choice A is incorrect because the sentence describes a problem, not an activity. Choice B is incorrect because the sentence concerns this year''s frost, not the orchards'' history. Choice C is incorrect because the festival is shortened, not permanently canceled, and no argument is made."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e7177ddd-7df8-57f7-6134-82cf3ed1c7c1','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"The lighthouse keeper''s daughter knew every sound the old tower made: the groan of the stairs in cold weather, the hum of the lamp, the rattle of the windows when the wind came from the east. So when, one night in March, she heard a sound she did not recognize, a slow and deliberate knocking from somewhere below, she sat up at once.","options":[{"id":"A","label":"To establish a character''s familiarity with a place so that an unfamiliar sound seems significant"},{"id":"B","label":"To explain how old lighthouses were constructed"},{"id":"C","label":"To describe the character''s fear of winter storms"},{"id":"D","label":"To show that the character dislikes living in the lighthouse"}]}'::jsonb,44,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e7177ddd-7df8-57f7-6134-82cf3ed1c7c1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text first lists the familiar sounds she knows and then shows her reacting immediately to one she does not recognize. Choice B is incorrect because the text mentions parts of the tower only as sources of sound. Choice C is incorrect because storms are not mentioned, and her reaction is to an unknown sound, not to weather. Choice D is incorrect because nothing suggests she dislikes her home."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4ebd46ba-ef02-3873-4d32-2f3ca617639d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Recipes in medieval European cookbooks rarely give exact quantities or cooking times. Instead, they tell the cook to add \"enough\" spice or to cook a dish \"until it is done.\" Historians explain that these books were written for experienced cooks who already knew the basic techniques and needed only reminders of a dish''s ingredients and steps.","options":[{"id":"A","label":"To argue that modern cookbooks should also leave out exact quantities"},{"id":"B","label":"To describe a feature of medieval cookbooks and explain why it existed"},{"id":"C","label":"To list ingredients that were common in medieval European dishes"},{"id":"D","label":"To show that medieval cooks lacked basic cooking skills"}]}'::jsonb,45,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4ebd46ba-ef02-3873-4d32-2f3ca617639d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the text notes that medieval recipes lacked exact measurements and then explains that they were written for experienced cooks. Choice A is incorrect because modern cookbooks are not discussed. Choice C is incorrect because no ingredients are listed. Choice D is incorrect because the text says the cooks already knew basic techniques."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ae8c9430-64ff-37b0-ac14-a6c4f611aeed','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Traffic engineers in one city replaced a busy four-way intersection with a roundabout. Some residents protested the change, worried that drivers would find the new design confusing. A year later, the city reported that crashes at the intersection had fallen by nearly half and that drivers'' average waiting time had also decreased.","options":[{"id":"A","label":"It presents a problem and lists possible solutions without choosing among them."},{"id":"B","label":"It describes a historical event and then explains what caused it."},{"id":"C","label":"It compares two cities'' approaches to improving traffic safety."},{"id":"D","label":"It describes a change, notes concerns about it, and then reports outcomes that followed."}]}'::jsonb,46,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ae8c9430-64ff-37b0-ac14-a6c4f611aeed','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the text describes the new roundabout, mentions residents'' worries, and then gives results from a year later. Choice A is incorrect because a single solution was chosen and carried out. Choice B is incorrect because the text reports results of a change, not causes of an event. Choice C is incorrect because only one city is discussed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('11b50962-b570-bc8c-58fe-01cdae4743db','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Sharks have existed for more than 400 million years, longer than there have been trees on Earth. Over that time, they have survived several mass extinctions that wiped out most other species. <u>Today, however, many shark populations are declining rapidly because of overfishing.</u>","options":[{"id":"A","label":"It gives an example of one of the mass extinctions mentioned earlier."},{"id":"B","label":"It explains how sharks survived earlier mass extinctions."},{"id":"C","label":"It contrasts sharks'' long record of survival with a present-day threat to them."},{"id":"D","label":"It supports the claim that sharks are older than trees."}]}'::jsonb,47,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('11b50962-b570-bc8c-58fe-01cdae4743db','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because \"however\" sets the current decline from overfishing against the long history of survival in the earlier sentences. Choice A is incorrect because overfishing is a current threat, not one of the past extinctions. Choice B is incorrect because the sentence does not explain how sharks survived. Choice D is incorrect because the sentence is about the present, not sharks'' age."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4889d04e-e75e-dfc3-98a7-17a76db80e37','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"The Dutch painter Johannes Vermeer completed relatively few works; fewer than forty paintings are attributed to him today. Yet paintings such as Girl with a Pearl Earring are among the most recognizable images in European art, admired especially for their subtle treatment of light falling across quiet interior scenes.","options":[{"id":"A","label":"To note that an artist produced few works but is nonetheless highly regarded"},{"id":"B","label":"To explain the techniques Vermeer used to make his paints"},{"id":"C","label":"To argue that Vermeer should have produced more paintings"},{"id":"D","label":"To compare Vermeer''s paintings with those of other Dutch artists"}]}'::jsonb,48,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4889d04e-e75e-dfc3-98a7-17a76db80e37','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text contrasts Vermeer''s small output with how recognizable and admired his paintings are, using \"Yet\" to link the two. Choice B is incorrect because paint-making is never discussed. Choice C is incorrect because the text makes no judgment about how many works he should have painted. Choice D is incorrect because no other artists are named."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a8c956bf-fcca-7d06-1a2e-5f95c90f2b30','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Tardigrades are tiny animals, usually less than a millimeter long, that live in moss, soil, and water. When their surroundings dry out, they can curl up, lose nearly all the water in their bodies, and enter a state in which their metabolism almost stops. In this state, some tardigrades have survived for years, reviving within hours once water returns.","options":[{"id":"A","label":"It introduces an animal and then describes an unusual ability it has."},{"id":"B","label":"It compares tardigrades with other animals that live in moss."},{"id":"C","label":"It describes an experiment and then questions its results."},{"id":"D","label":"It explains why tardigrades are becoming rare."}]}'::jsonb,49,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a8c956bf-fcca-7d06-1a2e-5f95c90f2b30','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the first sentence introduces tardigrades and the rest of the text describes their ability to survive drying out. Choice B is incorrect because no other animals are discussed. Choice C is incorrect because no experiment is described or questioned. Choice D is incorrect because the text says nothing about tardigrades becoming rare."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a5b57336-259a-1a86-0207-86df0d818ff3','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"The following text is from an original poem.\n\nThe kettle sings before the dawn,\nthe window frames a sky still gray;\nmy father''s coat is on, then gone,\nand footsteps take the hill away.\nI count the steps until they fade,\nthen listen to the house grow wide:\nthe clock, the cat, the lamp''s low shade,\nand all the morning still inside.","options":[{"id":"A","label":"To express the speaker''s anger that the father has left home"},{"id":"B","label":"To describe a storm approaching the speaker''s house"},{"id":"C","label":"To portray a speaker''s quiet awareness of the house after a parent leaves early in the morning"},{"id":"D","label":"To explain why the speaker wakes up before dawn every day"}]}'::jsonb,50,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a5b57336-259a-1a86-0207-86df0d818ff3','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the poem follows the father leaving before dawn and then the speaker listening to the house''s small sounds afterward. Choice A is incorrect because nothing in the poem expresses anger. Choice B is incorrect because a gray sky before dawn is not a storm. Choice D is incorrect because the poem describes one morning and gives no reason for the speaker''s waking."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('97bfb248-1ea5-bf7f-5297-291aa80bff8c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"In 1854, a cholera outbreak struck the Soho district of London. <u>The physician John Snow traced the addresses of people who had died and found that the cases clustered around a single public water pump on Broad Street.</u> After the handle of the pump was removed, new cases in the area declined.","options":[{"id":"A","label":"It explains why cholera was common throughout London."},{"id":"B","label":"It describes how the outbreak finally ended."},{"id":"C","label":"It introduces an objection to Snow''s conclusion."},{"id":"D","label":"It describes how a physician identified a likely source of the outbreak."}]}'::jsonb,51,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('97bfb248-1ea5-bf7f-5297-291aa80bff8c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence explains that Snow''s tracing of the victims'' addresses revealed a cluster of cases around one pump, pointing to it as the source. Choice A is incorrect because the sentence focuses on one district and one pump. Choice B is incorrect because the end of the outbreak is described in the next sentence. Choice C is incorrect because no objection is mentioned."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d8d19284-f6b1-3eac-4637-77610c76c718','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Some teachers have begun replacing part of their students'' homework with short reflection journals, in which students write a few sentences about what they learned that day. Teachers who use the journals say that the entries quickly reveal which ideas students found confusing, allowing them to adjust the next morning''s lesson.","options":[{"id":"A","label":"To argue that homework should be eliminated from schools"},{"id":"B","label":"To describe a teaching practice and a benefit that teachers report"},{"id":"C","label":"To explain step by step how students should write a reflection journal"},{"id":"D","label":"To compare the test scores of students who use journals with those who do not"}]}'::jsonb,52,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d8d19284-f6b1-3eac-4637-77610c76c718','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the text describes reflection journals and reports that teachers use them to spot confusion and adjust lessons. Choice A is incorrect because the journals replace only part of homework, and no argument for elimination is made. Choice C is incorrect because the text gives no step-by-step instructions. Choice D is incorrect because test scores are never mentioned."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6d247dda-f3e9-bf6c-768e-79c257276db9','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Bird migration has often been described as a simple response to cold weather. <u>But many birds leave their summer ranges while temperatures are still mild, and some depart from regions that rarely experience freezing temperatures at all.</u> Researchers now emphasize the role of food supply and day length, which change in predictable ways across the seasons and can trigger migration well before the weather turns.","options":[{"id":"A","label":"It presents observations that challenge the explanation mentioned in the first sentence."},{"id":"B","label":"It offers an example that supports the explanation mentioned in the first sentence."},{"id":"C","label":"It introduces the explanation that researchers now favor."},{"id":"D","label":"It describes how researchers measure temperatures in birds'' summer ranges."}]}'::jsonb,53,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6d247dda-f3e9-bf6c-768e-79c257276db9','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because birds leaving during mild weather or from warm regions undercuts the idea that migration is simply a response to cold. Choice B is incorrect because \"But\" signals that the sentence works against, not for, the first sentence. Choice C is incorrect because the favored explanation, food supply and day length, appears in the third sentence. Choice D is incorrect because no measurement methods are described."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4657dca6-d7aa-ba96-2a5f-dc7d09b718f6','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Many people imagine ancient Roman roads as simple stone surfaces laid directly on the ground. In fact, major Roman roads were built in layers: a foundation of large stones, then gravel and sand, and finally tightly fitted paving stones on top. Drainage ditches ran along the sides, and the surface was slightly curved so that rainwater would run off. These features help explain why some Roman roads are still usable today.","options":[{"id":"A","label":"To argue that surviving Roman roads should be restored"},{"id":"B","label":"To compare Roman roads with modern highways"},{"id":"C","label":"To describe the routes connecting Rome with its provinces"},{"id":"D","label":"To explain how the construction of Roman roads contributed to their durability"}]}'::jsonb,54,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4657dca6-d7aa-ba96-2a5f-dc7d09b718f6','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the text corrects a misconception by detailing the roads'' layers and drainage and then links these features to the roads'' survival. Choice A is incorrect because the text makes no argument about restoration. Choice B is incorrect because modern highways are not discussed. Choice C is incorrect because the text describes how the roads were built, not where they went."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7f340346-9471-5610-d0b6-ae569461e982','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentences in the text as a whole?","passage":"Adapted from Charlotte Perkins Gilman, \"The Yellow Wallpaper,\" 1892.\n\nIt is very seldom that mere ordinary people like John and myself secure ancestral halls for the summer. A colonial mansion, a hereditary estate, I would say a haunted house, and reach the height of romantic felicity, but that would be asking too much of fate! Still I will proudly declare that there is something queer about it. <u>Else, why should it be let so cheaply? And why have stood so long untenanted?</u>","options":[{"id":"A","label":"They express the narrator''s gratitude that the house was so affordable."},{"id":"B","label":"They offer the narrator''s reasons for suspecting that something is unusual about the house."},{"id":"C","label":"They explain why John chose this particular house for the summer."},{"id":"D","label":"They describe the architectural features of the colonial mansion."}]}'::jsonb,55,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7f340346-9471-5610-d0b6-ae569461e982','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because \"Else\" ties the questions to the narrator''s claim that there is \"something queer\" about the house, and the low rent and long vacancy are offered as evidence. Choice A is incorrect because the low price is treated as suspicious, not as something to be grateful for. Choice C is incorrect because the questions do not explain John''s reasons. Choice D is incorrect because the questions concern rent and vacancy, not architecture."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a925ccad-7c1d-2afc-b52d-872ce87aedbe','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"For decades, biologists disagreed about how to classify the giant panda. Some grouped it with raccoons, citing similarities in its teeth and skull, while others placed it with bears. The debate persisted until genetic studies in the 1980s showed that the giant panda is a bear, and that the red panda, despite its name, belongs to a separate lineage.","options":[{"id":"A","label":"It presents a hypothesis and explains why it cannot be tested."},{"id":"B","label":"It describes the history of a species'' habitat and its recent decline."},{"id":"C","label":"It describes a scientific disagreement and then explains how new evidence resolved it."},{"id":"D","label":"It compares two animals and argues that they should share a name."}]}'::jsonb,56,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a925ccad-7c1d-2afc-b52d-872ce87aedbe','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the text describes competing classifications and then reports that genetic studies settled the question. Choice A is incorrect because the question was in fact answered by evidence. Choice B is incorrect because habitat is never discussed. Choice D is incorrect because the text notes that the red panda is not closely related despite sharing a name."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e56592d7-c6bc-1399-2535-111c4da54e2f','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"In a study of online product reviews, researchers found that the first few reviews of a product strongly influenced the reviews that followed. Products whose earliest reviews happened to be positive went on to receive more positive reviews than similar products whose early reviews were negative, even when the products were of comparable quality. The researchers suggest that later reviewers may adjust their opinions to match what others have already written.","options":[{"id":"A","label":"To argue that online reviews are always unreliable and should be ignored"},{"id":"B","label":"To present a finding about how early reviews affect later ones and offer a possible explanation for it"},{"id":"C","label":"To explain how customers can write more useful product reviews"},{"id":"D","label":"To show that higher-quality products receive more positive reviews"}]}'::jsonb,57,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e56592d7-c6bc-1399-2535-111c4da54e2f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the text reports that early reviews shaped later ones and closes with the researchers'' suggested explanation. Choice A is incorrect because the text describes a bias without claiming reviews are always unreliable. Choice C is incorrect because no advice is given. Choice D is incorrect because the finding held even for products of comparable quality."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('df550b65-aa64-de8e-dad5-e16343d437a7','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"In December 1903, Orville and Wilbur Wright made the first powered airplane flights near Kitty Hawk, North Carolina. <u>The longest of the four flights that day lasted less than a minute and covered about 260 meters.</u> Within a few years, however, their improved aircraft could stay aloft for more than an hour.","options":[{"id":"A","label":"It explains why the brothers chose to fly near Kitty Hawk."},{"id":"B","label":"It describes the improvements that made longer flights possible."},{"id":"C","label":"It suggests that the first flights were not considered successful at the time."},{"id":"D","label":"It provides details that emphasize how limited the first flights were."}]}'::jsonb,58,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('df550b65-aa64-de8e-dad5-e16343d437a7','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the short duration and distance highlight how modest the first flights were, setting up the contrast with later hour-long flights. Choice A is incorrect because the sentence does not discuss the location. Choice B is incorrect because no improvements are described in it. Choice C is incorrect because the sentence gives measurements without judging the flights'' success."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4d07ff8d-c185-1b5f-f415-8f019740fb7b','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Critics sometimes treat musical quotation, in which a composer incorporates a recognizable melody from another work, as a sign of limited invention. Yet quotation can accomplish something original material cannot. Because listeners recognize the borrowed tune, its appearance in a new setting can carry associations, from nostalgia to irony, that the composer never needs to spell out.","options":[{"id":"A","label":"To explain how composers choose which melodies to borrow"},{"id":"B","label":"To argue that composers should avoid writing original material"},{"id":"C","label":"To challenge a negative view of a musical practice by describing an effect it can achieve"},{"id":"D","label":"To trace the history of musical quotation"}]}'::jsonb,59,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4d07ff8d-c185-1b5f-f415-8f019740fb7b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the text introduces critics'' view of quotation as unoriginal and then counters it with the associations a borrowed tune can carry. Choice A is incorrect because the text does not discuss how melodies are selected. Choice B is incorrect because the text defends quotation without rejecting original material. Choice D is incorrect because no history is given."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b7914e63-dd39-a58f-974e-833074be346c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Most of the methane released by cattle is produced by microbes in the rumen, the first chamber of the animal''s stomach. Some researchers are testing feed additives, including a type of red seaweed, that interfere with these microbes. In early trials, small amounts of the seaweed reduced methane emissions substantially, though scientists caution that long-term effects on the animals and on milk and meat quality are still being studied.","options":[{"id":"A","label":"It identifies the source of a problem, describes an approach to addressing it, and notes promising but preliminary results."},{"id":"B","label":"It describes a problem and argues that it cannot be solved."},{"id":"C","label":"It presents two competing explanations for a phenomenon."},{"id":"D","label":"It describes an experiment and explains why its results were rejected."}]}'::jsonb,60,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b7914e63-dd39-a58f-974e-833074be346c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text locates methane production in rumen microbes, introduces feed additives, and reports early success along with cautions. Choice B is incorrect because the text describes a possible solution. Choice C is incorrect because only one explanation of methane production is given. Choice D is incorrect because the results were promising, not rejected."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('067b8d6a-95f9-6a43-3ff6-259c9d5dc15d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Every evening my aunt walked to the end of the pier and back, the same distance at the same pace. <u>The fishermen set their watches by her, or claimed to.</u> On the evening she did not appear, the whole harbor seemed to notice at once, though no one said anything until the lamps were lit.","options":[{"id":"A","label":"It suggests that the fishermen disliked the aunt."},{"id":"B","label":"It explains why the aunt walked on the pier each evening."},{"id":"C","label":"It emphasizes the regularity of the aunt''s habit by describing how others regarded it."},{"id":"D","label":"It introduces a conflict between the aunt and the fishermen."}]}'::jsonb,61,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('067b8d6a-95f9-6a43-3ff6-259c9d5dc15d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the joke that fishermen set their watches by her shows how predictable her walk was, which makes her absence noticeable later. Choice A is incorrect because the remark is affectionate, not hostile. Choice B is incorrect because the sentence gives no reason for the walks. Choice D is incorrect because no conflict is described."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('27729e5b-854d-63bf-27d5-318708890642','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Economists have long noted a puzzle: many people buy both insurance, which protects against a small chance of a large loss, and lottery tickets, which offer a small chance of a large gain. If people simply avoided risk, they would not buy lottery tickets; if they simply sought risk, they would not buy insurance. One proposed resolution holds that people overweight unlikely outcomes, making both the feared disaster and the dreamed-of jackpot seem more probable than they are.","options":[{"id":"A","label":"It describes a seemingly contradictory pattern of behavior and then presents one proposed explanation for it."},{"id":"B","label":"It argues that insurance is a better use of money than lottery tickets."},{"id":"C","label":"It explains how economists calculate the odds of winning a lottery."},{"id":"D","label":"It presents two explanations for a behavior and concludes that both are wrong."}]}'::jsonb,62,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('27729e5b-854d-63bf-27d5-318708890642','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text sets out the puzzle of buying both insurance and lottery tickets and then offers the overweighting of unlikely outcomes as a resolution. Choice B is incorrect because the text does not judge either purchase. Choice C is incorrect because no calculations are described. Choice D is incorrect because simple risk avoidance and risk seeking are shown to fail, but the text then offers an explanation rather than rejecting all of them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f0c446ec-3a4e-4321-5ff4-fa3f806bc7aa','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Accounts of the California Gold Rush that began in 1848 often focus on the miners who struck it rich. Far more people, however, earned steady incomes by selling goods and services to the miners, from tools and food to lodging and laundry, often at very high prices. For many who arrived in California during those years, the surest path to profit lay not in the gold fields but in the towns that sprang up around them.","options":[{"id":"A","label":"To argue that very few miners ever found gold"},{"id":"B","label":"To describe the methods miners used to extract gold"},{"id":"C","label":"To explain why prices fell in Gold Rush towns"},{"id":"D","label":"To shift attention from a commonly emphasized group to a group that more often prospered"}]}'::jsonb,63,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f0c446ec-3a4e-4321-5ff4-fa3f806bc7aa','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the text moves from the usual focus on lucky miners to the merchants who more reliably made money. Choice A is incorrect because the text does not claim that few miners found gold. Choice B is incorrect because mining methods are not discussed. Choice C is incorrect because the text says prices were high."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('16931540-13a5-38df-e7be-e5f0a705125c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"<u>Astronomers cannot directly see most planets outside our solar system, because the planets are faint and lie very close to their much brighter stars.</u> Instead, many such planets are detected using the transit method. When a planet passes in front of its star from our point of view, the star''s brightness dips slightly, and by measuring the size and timing of these dips, astronomers can estimate the planet''s size and orbit.","options":[{"id":"A","label":"It describes the transit method in detail."},{"id":"B","label":"It explains a difficulty that the method described in the rest of the text helps overcome."},{"id":"C","label":"It argues that the transit method is unreliable."},{"id":"D","label":"It identifies planets that astronomers have seen directly."}]}'::jsonb,64,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('16931540-13a5-38df-e7be-e5f0a705125c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the sentence explains why planets are hard to see, and \"Instead\" introduces the transit method as a way around that problem. Choice A is incorrect because the transit method is described only in the later sentences. Choice C is incorrect because nothing in the text questions the method. Choice D is incorrect because the sentence names no planets."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9aa70374-2f08-66e9-7e43-f6a973ee7222','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"The haiku is often taught in English classrooms as a poem of exactly seventeen syllables arranged in lines of five, seven, and five. That rule, however, translates imperfectly from Japanese, which counts sound units called on that are generally shorter than English syllables. For this reason, many poets writing haiku in English use fewer than seventeen syllables, aiming to match the brevity of the Japanese form rather than its exact count.","options":[{"id":"A","label":"To argue that haiku cannot be successfully written in English"},{"id":"B","label":"To describe the history of the haiku in Japan"},{"id":"C","label":"To explain why many haiku written in English depart from a commonly taught rule"},{"id":"D","label":"To teach readers how to count syllables in English"}]}'::jsonb,65,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9aa70374-2f08-66e9-7e43-f6a973ee7222','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the text describes the seventeen-syllable rule, explains why it fits English poorly, and shows how poets adapt. Choice A is incorrect because the text describes poets successfully adapting the form. Choice B is incorrect because the haiku''s history in Japan is not discussed. Choice D is incorrect because the text gives no instructions for counting syllables."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('07fa615f-a528-fe8f-02ec-c373b0b94bbf','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Public opinion polls typically survey about a thousand people to estimate the views of millions. This can seem implausible, but the accuracy of a well-designed random sample depends far more on how participants are chosen and how many are surveyed than on what share of the population is included. <u>A poll of 1,000 randomly selected adults can estimate national opinion about as precisely as a poll of 1,000 adults can estimate the opinion of a single city.</u>","options":[{"id":"A","label":"It identifies a problem with the method described in the first sentence."},{"id":"B","label":"It illustrates the claim in the previous sentence with a comparison."},{"id":"C","label":"It explains how pollsters select participants randomly."},{"id":"D","label":"It argues that city polls are less accurate than national polls."}]}'::jsonb,66,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-026","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('07fa615f-a528-fe8f-02ec-c373b0b94bbf','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the comparison of a national and a city poll of the same size shows that the share of the population sampled matters little, which is the previous sentence''s claim. Choice A is incorrect because the sentence supports rather than criticizes polling a thousand people. Choice C is incorrect because no selection procedure is described. Choice D is incorrect because the sentence says the two polls are about equally precise."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f5308299-3f09-2170-41dc-a8bbd596f092','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Critics who read the novel as a celebration of its heroine''s independence must contend with its final chapter, in which she accepts a marriage she has spent three hundred pages resisting. Some dismiss the ending as a concession to the conventions of the period, a happy resolution attached to satisfy readers. Yet the chapter''s language—clipped, formal, and conspicuously lacking the heroine''s earlier wit—suggests that the author may have intended the ending to read as a defeat disguised as a triumph.","options":[{"id":"A","label":"It identifies a challenge to an interpretation, presents one response to that challenge, and then offers an alternative reading of the challenging material."},{"id":"B","label":"It presents an interpretation, provides evidence for it, and then concedes that the interpretation is probably wrong."},{"id":"C","label":"It summarizes a novel''s plot and then evaluates the novel''s literary merit."},{"id":"D","label":"It compares the endings of two novels and argues that one is more realistic."}]}'::jsonb,67,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-027","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f5308299-3f09-2170-41dc-a8bbd596f092','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text notes that the ending challenges the \"independence\" reading, reports that some dismiss the ending as convention, and then proposes that its language marks it as a disguised defeat. Choice B is incorrect because the text does not concede that any interpretation is wrong; it offers a new reading of the ending. Choice C is incorrect because the text does not summarize the plot or judge the novel''s quality. Choice D is incorrect because only one novel is discussed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('01270cd9-b481-ce64-d36d-26e8e2a4eff3','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Among the many proposed functions of the peacock''s elaborate tail, the most widely accepted holds that it signals a male''s quality to choosy females. <u>The hypothesis faces an apparent difficulty: if females consistently prefer the most ornate tails, the variation among males on which their choice depends should eventually disappear.</u> One proposed answer is that ornament size depends on overall condition, which reflects so many genes that mutation continually supplies new variation.","options":[{"id":"A","label":"It provides experimental evidence that supports the hypothesis."},{"id":"B","label":"It presents an alternative hypothesis about the tail''s function."},{"id":"C","label":"It resolves the problem described in the final sentence."},{"id":"D","label":"It raises a theoretical problem for the hypothesis introduced in the first sentence."}]}'::jsonb,68,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-028","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('01270cd9-b481-ce64-d36d-26e8e2a4eff3','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence identifies an \"apparent difficulty,\" reasoning that female choice should erase the variation the hypothesis depends on. Choice A is incorrect because the sentence offers reasoning that challenges the hypothesis, not evidence that supports it. Choice B is incorrect because the sentence questions the existing hypothesis rather than proposing a different function. Choice C is incorrect because the final sentence answers the problem raised by the underlined sentence, not the other way around."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f904eba2-6de6-bcfc-ada8-7a22c6e605b0','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"It is tempting to read the absence of women''s names from the guild records of a fifteenth-century city as evidence that women played no part in its crafts. But guild records listed only masters, and in many trades a master''s household, including his wife, daughters, and servants, performed much of the work. Widows, moreover, frequently continued their husbands'' workshops and in some cities appear in tax rolls as heads of businesses even when guild lists omit them.","options":[{"id":"A","label":"To argue that guilds deliberately excluded women from all forms of craft work"},{"id":"B","label":"To argue that a particular kind of record understates women''s participation in a city''s crafts"},{"id":"C","label":"To show that tax rolls are more accurate than guild records for every historical purpose"},{"id":"D","label":"To explain why widows were allowed to join guilds as masters"}]}'::jsonb,69,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-029","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f904eba2-6de6-bcfc-ada8-7a22c6e605b0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the text warns against reading the absence of women in guild lists as nonparticipation and gives reasons the lists miss women''s work. Choice A is incorrect because the text describes women doing craft work, and it attributes their absence to how records were kept rather than to deliberate exclusion. Choice C is incorrect because tax rolls are cited only to show that widows ran businesses, not as generally superior sources. Choice D is incorrect because the text says widows ran workshops even when guild lists omit them, not that they joined as masters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d7e4b594-230a-2227-ec8d-3af92a0660e8','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"A common objection to thought experiments in philosophy is that they ask us to consult our intuitions about scenarios too strange for those intuitions to be trustworthy. Defenders reply that the strangeness is the point: by stripping away features that ordinarily accompany a situation, a thought experiment isolates a single factor and lets us ask whether that factor matters on its own. <u>The objection, on this view, mistakes a method''s deliberate design for an accidental flaw.</u>","options":[{"id":"A","label":"It concedes that the objection identifies a genuine weakness of thought experiments."},{"id":"B","label":"It introduces a new objection to thought experiments."},{"id":"C","label":"It sums up the defenders'' reply by recasting the feature criticized in the objection as intentional."},{"id":"D","label":"It provides a specific example of a thought experiment."}]}'::jsonb,70,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-030","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d7e4b594-230a-2227-ec8d-3af92a0660e8','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the sentence restates the defenders'' point that strangeness is a designed feature, not a defect, using \"on this view\" to mark it as their position. Choice A is incorrect because the sentence rejects the objection rather than granting it. Choice B is incorrect because the sentence responds to the existing objection instead of raising a new one. Choice D is incorrect because no particular thought experiment is described."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('54403227-b54f-0d72-6724-3917c6221c1c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"Adapted from Kate Chopin, The Awakening, 1899.\n\n<u>The voice of the sea is seductive; never ceasing, whispering, clamoring, murmuring, inviting the soul to wander for a spell in abysses of solitude; to lose itself in mazes of inward contemplation.</u> The voice of the sea speaks to the soul. The touch of the sea is sensuous, enfolding the body in its soft, close embrace.","options":[{"id":"A","label":"It introduces a contrast between the sea''s threatening voice and its gentle touch."},{"id":"B","label":"It suggests that the sea''s voice is frightening rather than appealing."},{"id":"C","label":"It identifies the particular character who hears the sea."},{"id":"D","label":"It characterizes the sea''s voice as alluring and develops that characterization by describing how the voice seems to draw the soul inward."}]}'::jsonb,71,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-031","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('54403227-b54f-0d72-6724-3917c6221c1c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the sentence calls the sea''s voice \"seductive\" and then lists how it whispers and murmurs, \"inviting the soul\" toward solitude and inward contemplation. Choice A is incorrect because the voice is presented as alluring, like the touch, not as threatening. Choice B is incorrect because \"seductive\" and \"inviting\" describe appeal, and even the \"abysses of solitude\" are something the soul is invited, not frightened, into. Choice C is incorrect because no character is named."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3d599741-a598-42c6-def7-1df4da503073','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the overall structure of the text?","passage":"Studies comparing the earnings of college graduates with those of nongraduates consistently find a large gap. Skeptics point out that the comparison may partly reflect who chooses to attend college: people who might have earned more regardless. To address this, some researchers have compared applicants who fell just above and just below the admission cutoff at selective programs, reasoning that such applicants are otherwise similar. These studies generally find that admission itself raises earnings, though by less than the raw gap would suggest.","options":[{"id":"A","label":"It reports a finding, raises a concern about how to interpret it, describes a method designed to address that concern, and summarizes what the method reveals."},{"id":"B","label":"It presents a hypothesis, describes evidence against it, and concludes that the hypothesis should be rejected."},{"id":"C","label":"It describes a method, identifies a flaw in that method, and then reports a finding that the flaw invalidates."},{"id":"D","label":"It describes a government policy and weighs its costs against its benefits."}]}'::jsonb,72,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-032","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3d599741-a598-42c6-def7-1df4da503073','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text gives the earnings gap, notes the self-selection concern, describes the admission-cutoff comparison, and reports its result. Choice B is incorrect because the later studies confirm an effect, though a smaller one, rather than rejecting the idea. Choice C is incorrect because the cutoff comparison is introduced to address the concern about the original comparison, and its finding is presented as credible rather than invalidated. Choice D is incorrect because no policy is discussed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e9d67ed8-c3d1-efcf-5bbf-a6bd88e43b37','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"The fact that some birds can learn to imitate human speech has often been taken as evidence of exceptional intelligence. Yet vocal imitation is a narrower skill than this inference assumes. It depends on specialized brain circuits for learning sounds, which have evolved independently in only a few groups of birds, including parrots, songbirds, and hummingbirds. A species may excel at imitation while performing unremarkably on other cognitive tasks, and the reverse is also true.","options":[{"id":"A","label":"To argue that parrots are less intelligent than other birds"},{"id":"B","label":"To explain the process by which parrots learn to imitate human speech"},{"id":"C","label":"To argue that vocal imitation evolved because it helps birds solve other cognitive tasks"},{"id":"D","label":"To caution against treating one specialized ability as a general measure of intelligence"}]}'::jsonb,73,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-033","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e9d67ed8-c3d1-efcf-5bbf-a6bd88e43b37','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because the text challenges the inference from imitation to intelligence by explaining that imitation relies on specialized circuits and does not track performance on other tasks. Choice A is incorrect because the text does not rank parrots'' intelligence; it questions what imitation shows. Choice B is incorrect because the text mentions brain circuits only to show the skill is specialized, not to explain how learning happens. Choice C is incorrect because the text says imitation can be unrelated to performance on other cognitive tasks and does not explain why the skill evolved."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0367f080-af3d-867b-3bfe-1e4c7fb57ee4','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","passage":"The architect''s buildings have been praised as \"honest\" for exposing their concrete and steel rather than hiding them behind decorative facades. <u>The word suggests a moral virtue, but it can obscure the extent to which such exposure is itself a style, carefully composed and often requiring costly finishing to make raw materials look appealing.</u> A building that displays its structure may be no less calculated in its effect than one that conceals it.","options":[{"id":"A","label":"It provides further examples of the honesty praised in the first sentence."},{"id":"B","label":"It argues that exposed materials are less expensive than decorative facades."},{"id":"C","label":"It questions what a term used in the first sentence implies by pointing to the deliberate artistry involved."},{"id":"D","label":"It explains the engineering advantages of exposing concrete and steel."}]}'::jsonb,74,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-034","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0367f080-af3d-867b-3bfe-1e4c7fb57ee4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because the sentence challenges the moral sense of \"honest\" by showing that exposure is a composed style, which leads into the final sentence''s point. Choice A is incorrect because the sentence complicates the praise rather than adding examples of it. Choice B is incorrect because the sentence says exposure often requires costly finishing. Choice D is incorrect because the sentence concerns appearance and style, not engineering."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b60e4ec0-94e8-ad2b-3cb0-ee87fd662d95','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best states the main purpose of the text?","passage":"Economic historians once explained the collapse of a region''s textile industry as the inevitable result of competition from cheaper producers abroad. Recent work complicates that account without overturning it. Foreign competition did intensify, but mills that had invested in new machinery during the preceding decade weathered it far better than those that had not, suggesting that managers'' earlier decisions shaped which firms survived.","options":[{"id":"A","label":"To refine an explanation by showing that a factor besides the one traditionally emphasized affected outcomes"},{"id":"B","label":"To reject the claim that foreign competition affected the region''s textile industry"},{"id":"C","label":"To recommend that struggling industries invest in new machinery"},{"id":"D","label":"To describe the types of machinery the mills introduced"}]}'::jsonb,75,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"text_structure_and_purpose","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-tsp-035","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b60e4ec0-94e8-ad2b-3cb0-ee87fd662d95','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because the text accepts that foreign competition mattered but adds that earlier investment decisions influenced which mills survived. Choice B is incorrect because the text says recent work does not overturn the account and that competition \"did intensify.\" Choice C is incorrect because the text analyzes past outcomes and makes no recommendation. Choice D is incorrect because the machinery is mentioned only as an investment, without description."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('87ea4b7c-b553-740e-ff7d-6a0bb0febb93','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the educators in Text 2 most likely respond to the teachers in Text 1?","passage":"Text 1: Many teachers believe that letting students choose which books to read in class increases their interest in reading. When students pick their own books, these teachers argue, they are more likely to finish them and to keep reading for pleasure outside school.\n\nText 2: Free choice of books can boost students'' enthusiasm, but some educators worry that students given complete freedom will avoid challenging texts. They recommend offering choices from a list that includes books of varying difficulty, so that students stay engaged while still being stretched.","options":[{"id":"A","label":"By agreeing that choice can increase interest while suggesting that choices be guided so students also read challenging books"},{"id":"B","label":"By arguing that letting students choose books reduces their interest in reading"},{"id":"C","label":"By insisting that students read only books assigned by their teachers"},{"id":"D","label":"By agreeing that students should be allowed to read any book they want without limits"}]}'::jsonb,76,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('87ea4b7c-b553-740e-ff7d-6a0bb0febb93','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 2 grants that choice \"can boost students'' enthusiasm\" but recommends a list of varied difficulty to keep students stretched. Choice B is incorrect because Text 2 accepts that choice increases enthusiasm. Choice C is incorrect because Text 2 still recommends offering students choices. Choice D is incorrect because Text 2 worries about complete freedom and proposes limits."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9894c3b8-1c23-1ae1-7ed9-2b68a42f7ccd','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, the scientists in Text 1 and the researchers in Text 2 would most likely agree that","passage":"Text 1: Many scientists argue that the dinosaurs were wiped out by an asteroid that struck Earth about 66 million years ago. The impact would have thrown enormous amounts of dust into the atmosphere, blocking sunlight and causing the collapse of plant life and of the animals that depended on it.\n\nText 2: Other researchers point to massive volcanic eruptions in what is now India that occurred around the same time. These eruptions released huge quantities of gas that could have changed the climate. Some scientists suggest that the volcanoes and the asteroid together caused the extinction.","options":[{"id":"A","label":"the asteroid impact alone caused the extinction of the dinosaurs."},{"id":"B","label":"volcanic eruptions were the only cause of the extinction."},{"id":"C","label":"the dinosaurs had already died out before the asteroid struck."},{"id":"D","label":"an event that altered Earth''s environment contributed to the extinction of the dinosaurs."}]}'::jsonb,77,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9894c3b8-1c23-1ae1-7ed9-2b68a42f7ccd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because both texts attribute the extinction at least partly to a major event, an impact or eruptions, that changed the environment. Choice A is incorrect because Text 2 points to volcanoes and suggests that the asteroid may have acted together with them. Choice B is incorrect because Text 1 credits the asteroid, and even Text 2 mentions a combined cause. Choice C is incorrect because neither text suggests that dinosaurs were extinct before the impact."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c9b201b1-91b5-fe07-0504-85a8b1cd7644','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the shop owners in Text 2 most likely respond to the planners in Text 1?","passage":"Text 1: City planners in Riverton have proposed turning a downtown parking lot into a public park. They argue that green space will attract visitors to the downtown area and make it a more pleasant place for residents to spend time.\n\nText 2: Some Riverton shop owners oppose replacing the parking lot. They worry that customers who drive downtown will have nowhere to park and will choose to shop elsewhere instead, which could hurt local businesses.","options":[{"id":"A","label":"By agreeing that a park would bring more customers to their shops"},{"id":"B","label":"By arguing that losing the parking lot could reduce the number of customers who come downtown"},{"id":"C","label":"By suggesting that the park be built in a larger city"},{"id":"D","label":"By claiming that residents dislike green space"}]}'::jsonb,78,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c9b201b1-91b5-fe07-0504-85a8b1cd7644','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the shop owners worry that drivers will have nowhere to park and will shop elsewhere, which challenges the planners'' claim that the park will attract visitors. Choice A is incorrect because the shop owners oppose the plan. Choice C is incorrect because neither text mentions another city. Choice D is incorrect because the shop owners'' concern is parking, not residents'' feelings about green space."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e461fea5-f2b7-eee5-439b-934162c95efd','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the readers described in Text 1?","passage":"Text 1: Many readers see the poet''s frequent images of birds as symbols of freedom. In poem after poem, birds soar above fields and cities, escaping the troubles of the people below them.\n\nText 2: The poet''s birds are not always free. In several poems, they are caged, injured, or unable to leave a frozen landscape. These images suggest that the poet also used birds to explore feelings of confinement and helplessness.","options":[{"id":"A","label":"By agreeing that the poet''s birds always symbolize freedom"},{"id":"B","label":"By claiming that the poet rarely wrote about birds"},{"id":"C","label":"By arguing that their interpretation overlooks poems in which birds represent something other than freedom"},{"id":"D","label":"By arguing that the poems about cities matter more than the poems about fields"}]}'::jsonb,79,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e461fea5-f2b7-eee5-439b-934162c95efd','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 2 points to caged and injured birds that express confinement, which the freedom reading leaves out. Choice A is incorrect because Text 2 says the poet''s birds \"are not always free.\" Choice B is incorrect because Text 2 discusses several poems with birds. Choice D is incorrect because neither text ranks the poems by setting."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('56a552ff-ff87-f57f-d12e-a6a04ae47188','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes a difference in how the researchers in the two texts view remote work?","passage":"Text 1: Some researchers argue that working from home makes employees more productive. Remote workers spend no time commuting and face fewer interruptions from coworkers, leaving them more time and focus for their individual tasks.\n\nText 2: Other researchers caution that remote work can make collaboration harder. Employees working from home may miss the quick, informal conversations that help teams solve problems together, which could lower productivity on group projects.","options":[{"id":"A","label":"Text 1 focuses on commuting costs, while Text 2 focuses on the cost of office space."},{"id":"B","label":"Text 1 emphasizes its benefits for individual tasks, while Text 2 emphasizes its possible drawbacks for teamwork."},{"id":"C","label":"Text 1 argues that remote work should be banned, while Text 2 argues that it should be required."},{"id":"D","label":"Both texts argue that remote work reduces productivity in every situation."}]}'::jsonb,80,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('56a552ff-ff87-f57f-d12e-a6a04ae47188','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Text 1 stresses fewer interruptions and more focus for individual work, while Text 2 stresses lost informal conversation on group projects. Choice A is incorrect because office space is never mentioned. Choice C is incorrect because neither text calls for a ban or a requirement. Choice D is incorrect because Text 1 says remote work increases productivity."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8c0e97f5-2d7d-614c-d56a-628b6f5f4947','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the popular histories described in Text 1?","passage":"Text 1: Popular histories often present major inventions as the work of a single brilliant individual. In this telling, an inventor working alone has a sudden insight that changes the world almost overnight.\n\nText 2: Studies of invention show that many breakthroughs were developed at nearly the same time by several people working independently, each building on earlier discoveries. Such cases suggest that inventions depend heavily on the knowledge and tools available at a particular moment in history.","options":[{"id":"A","label":"By agreeing that most inventions result from one person''s sudden insight"},{"id":"B","label":"By arguing that inventions rarely have much effect on the world"},{"id":"C","label":"By claiming that inventors produce better work when they work alone"},{"id":"D","label":"By pointing out that they overlook the role of earlier discoveries and of other inventors"}]}'::jsonb,81,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8c0e97f5-2d7d-614c-d56a-628b6f5f4947','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because Text 2 shows that inventions often arose among several people at once and built on earlier work, which the lone-genius story ignores. Choice A is incorrect because Text 2 challenges that view. Choice B is incorrect because Text 2 discusses where inventions come from, not their impact. Choice C is incorrect because Text 2 emphasizes shared knowledge rather than solitary work."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('88eb8e2c-ac46-c757-9562-14dfb211499c','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, the researchers in Text 2 would most likely say that the studies cited in Text 1","passage":"Text 1: Some nutrition researchers recommend eating breakfast every day. They cite studies finding that people who regularly eat breakfast tend to weigh less than people who skip it.\n\nText 2: In controlled trials in which participants were randomly assigned either to eat breakfast or to skip it, researchers found little difference in weight change between the two groups. Earlier studies, these researchers note, may simply reflect other healthy habits that breakfast eaters tend to have.","options":[{"id":"A","label":"may not show that eating breakfast itself leads to lower weight."},{"id":"B","label":"prove that skipping breakfast causes weight gain."},{"id":"C","label":"were controlled trials in which participants were randomly assigned to groups."},{"id":"D","label":"show that people who eat breakfast have less healthy habits."}]}'::jsonb,82,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('88eb8e2c-ac46-c757-9562-14dfb211499c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 2 suggests the weight difference could come from breakfast eaters'' other habits, so it may not be caused by breakfast. Choice B is incorrect because Text 2''s trials found little effect of skipping breakfast. Choice C is incorrect because Text 2 contrasts its own randomized trials with the earlier studies. Choice D is incorrect because Text 2 suggests breakfast eaters tend to have healthier habits."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('301e48cc-6604-8d51-1bb2-2db101f0f6e3','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes the relationship between the two texts?","passage":"Text 1: Many art museums prohibit visitors from photographing the artworks on display. Museum staff argue that cameras distract visitors from looking closely at the art and spoil the experience for others nearby.\n\nText 2: Some museums now encourage visitors to take photographs. Their staff argue that photos shared with friends online introduce the museum to people who might never have visited otherwise.","options":[{"id":"A","label":"Both texts argue that photography should be banned in museums."},{"id":"B","label":"Text 2 provides an example of the policy described in Text 1."},{"id":"C","label":"They present different views about whether museums should allow visitors to take photographs."},{"id":"D","label":"Text 1 explains the history of a museum policy that Text 2 describes in more detail."}]}'::jsonb,83,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('301e48cc-6604-8d51-1bb2-2db101f0f6e3','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 1 explains why some museums ban photography, while Text 2 explains why others encourage it. Choice A is incorrect because Text 2 supports photography. Choice B is incorrect because Text 2 describes the opposite policy. Choice D is incorrect because neither text gives a history, and the texts describe opposing policies."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9bd8d87b-12e7-1621-cfa9-2f7ecd03b413','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, both groups of ecologists would most likely agree that","passage":"Text 1: Wolves were reintroduced to Yellowstone National Park in 1995. Some ecologists credit the wolves with reducing elk numbers, which allowed willow and aspen trees, previously overgrazed by elk, to recover along streams.\n\nText 2: Other ecologists agree that elk numbers declined after the wolves returned but argue that willows recovered unevenly. In some areas, they note, streams had changed so much during the years when elk were abundant that willows still struggle to grow even with fewer elk.","options":[{"id":"A","label":"elk numbers declined after wolves were reintroduced."},{"id":"B","label":"willows have fully recovered in all areas of the park."},{"id":"C","label":"streams in the park were not affected by elk."},{"id":"D","label":"the wolves had no effect on the park''s ecosystem."}]}'::jsonb,84,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9bd8d87b-12e7-1621-cfa9-2f7ecd03b413','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 1 credits wolves with reducing elk, and Text 2 explicitly agrees that elk numbers declined. Choice B is incorrect because Text 2 says willows recovered unevenly. Choice C is incorrect because Text 2 says streams changed while elk were abundant. Choice D is incorrect because both texts link the wolves'' return to fewer elk."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0531b504-c025-8a0f-b979-58ac22ce2c70','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes how Text 2 relates to Text 1?","passage":"Text 1: Researchers studying American crows have found that the birds can recognize individual human faces. In one study, crows that had been captured by researchers wearing a particular mask scolded anyone wearing that mask for years afterward, even people who had never harmed them.\n\nText 2: The crows'' reactions show more than individual memory. Crows that had never been captured also began scolding the mask, apparently learning from the reactions of other crows. This suggests that knowledge about threats can spread through a crow population socially.","options":[{"id":"A","label":"It disputes the claim that crows can recognize human faces."},{"id":"B","label":"It extends the findings described in Text 1 by showing that the response spread to crows that had not been captured."},{"id":"C","label":"It offers a different explanation for why captured crows scolded the mask."},{"id":"D","label":"It describes a study that failed to reproduce the results reported in Text 1."}]}'::jsonb,85,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0531b504-c025-8a0f-b979-58ac22ce2c70','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Text 2 accepts the face-recognition finding and adds that uncaptured crows learned to scold the mask from others. Choice A is incorrect because Text 2 builds on, rather than challenges, the recognition finding. Choice C is incorrect because Text 2 focuses on crows that were never captured, not on a new explanation for the captured ones. Choice D is incorrect because Text 2 describes a further result, not a failure to replicate."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b928b3d7-daa3-7703-7554-7944eb981c17','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the economists in Text 2 most likely respond to the supporters in Text 1?","passage":"Text 1: Rent control, which limits how much landlords can raise rents, protects tenants from sudden increases and helps long-term residents remain in their neighborhoods. For families on fixed incomes, supporters argue, this stability can mean the difference between staying and being forced out.\n\nText 2: Many economists agree that rent control benefits tenants who already live in controlled apartments. But studies suggest that, over time, some landlords respond by converting units to condominiums or cutting back on maintenance, shrinking the supply of rental housing available to newcomers.","options":[{"id":"A","label":"By arguing that rent control harms the tenants who already live in controlled apartments"},{"id":"B","label":"By agreeing that rent control has no significant drawbacks"},{"id":"C","label":"By claiming that families on fixed incomes rarely rent apartments"},{"id":"D","label":"By acknowledging the benefit to current tenants while warning about effects on the wider rental market"}]}'::jsonb,86,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b928b3d7-daa3-7703-7554-7944eb981c17','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because Text 2 agrees that current tenants benefit but cites landlords'' responses that reduce rental supply for newcomers. Choice A is incorrect because Text 2 says current tenants benefit. Choice B is incorrect because Text 2 describes drawbacks. Choice C is incorrect because Text 2 says nothing about who rents apartments."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('66a287c0-cb74-c84e-bd0d-dcdcbd922517','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the assumption described in Text 1?","passage":"Text 1: Readers of the novel often treat its narrator as the author''s mouthpiece. They assume that the narrator''s confident judgments of the other characters are the judgments the novel itself asks readers to share.\n\nText 2: The narrator''s pronouncements are repeatedly undercut by events in the novel. Characters he dismisses as foolish prove wise, and the character he most admires comes to ruin. These reversals suggest that the author wanted readers to question the narrator rather than trust him.","options":[{"id":"A","label":"By agreeing that the narrator''s judgments express the novel''s point of view"},{"id":"B","label":"By claiming that the narrator rarely passes judgment on other characters"},{"id":"C","label":"By arguing that the novel''s events give readers reason to doubt that the narrator speaks for the novel"},{"id":"D","label":"By suggesting that readers should disregard the events of the novel"}]}'::jsonb,87,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('66a287c0-cb74-c84e-bd0d-dcdcbd922517','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 2 points to events that contradict the narrator''s judgments, which undermines the assumption that he speaks for the novel. Choice A is incorrect because Text 2 argues that readers should question the narrator. Choice B is incorrect because Text 2 describes the narrator''s frequent pronouncements. Choice D is incorrect because Text 2 uses the events as its main evidence."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fb346782-4a31-117d-38de-eef52f2efeac','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the assumption described in Text 1?","passage":"Text 1: Many biologists once assumed that plants respond to insect attacks only at the site of the damage, producing defensive chemicals in the chewed leaf to discourage further feeding.\n\nText 2: Experiments with tomato plants show that when one leaf is damaged, the plant sends signals through its tissues, and undamaged leaves far from the injury begin producing defensive chemicals within hours. Some plants even release airborne compounds that appear to trigger defenses in neighboring plants.","options":[{"id":"A","label":"By agreeing that plants defend only the leaf that has been damaged"},{"id":"B","label":"By arguing that plants are unable to produce defensive chemicals"},{"id":"C","label":"By claiming that insects avoid feeding on tomato plants entirely"},{"id":"D","label":"By noting that plant defenses can extend well beyond the site of the damage"}]}'::jsonb,88,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fb346782-4a31-117d-38de-eef52f2efeac','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because Text 2 describes defenses in distant, undamaged leaves and even in neighboring plants, contradicting the idea that responses stay at the damaged site. Choice A is incorrect because Text 2 contradicts that assumption. Choice B is incorrect because both texts describe plants producing defensive chemicals. Choice C is incorrect because Text 2 describes tomato leaves being damaged, so insects do feed on them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('72f48bba-96bf-b53b-a43b-ae148d8f7c8d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely view the claim in Text 1?","passage":"Text 1: The rapid spread of the printing press in Europe after the mid-1400s is often credited with fueling the Protestant Reformation of the 1500s. Printed pamphlets allowed reformers'' ideas to reach audiences far beyond the reach of any single preacher.\n\nText 2: Printing certainly helped reformers, but the same presses also produced vast numbers of pamphlets defending the Church. What made reform messages succeed in some regions was not printing alone but the support of local rulers who protected reformers and allowed their writings to circulate.","options":[{"id":"A","label":"As overstating the role of printing by neglecting the political conditions that shaped its effects"},{"id":"B","label":"As correct, because printing presses were used only by reformers"},{"id":"C","label":"As mistaken, because printing had no effect on the spread of reform"},{"id":"D","label":"As irrelevant, because few people at the time read pamphlets"}]}'::jsonb,89,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('72f48bba-96bf-b53b-a43b-ae148d8f7c8d','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 2 grants that printing helped but argues that rulers'' protection, not printing alone, determined where reform succeeded. Choice B is incorrect because Text 2 says the presses also served the Church''s defenders. Choice C is incorrect because Text 2 says printing \"certainly helped reformers.\" Choice D is incorrect because Text 2 describes vast numbers of pamphlets and does not suggest they went unread."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e1400447-afef-3d25-557f-b9bd52aa1da6','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, the researchers in Text 2 would most likely say that the conclusion in Text 1","passage":"Text 1: Some psychologists argue that offering people too many options can be counterproductive. In one well-known experiment, shoppers who sampled from a display of 24 jams were less likely to buy any jam than shoppers who sampled from a display of only 6.\n\nText 2: Later researchers repeated such \"choice overload\" experiments in many settings. Combining the results, they found the effect to be inconsistent: sometimes more options reduced choosing, but often they had no effect or even increased satisfaction, depending on factors such as how familiar people were with the products.","options":[{"id":"A","label":"has been confirmed in nearly every setting in which it has been tested."},{"id":"B","label":"holds in some circumstances but cannot be assumed to apply generally."},{"id":"C","label":"is false, because more options always increase satisfaction."},{"id":"D","label":"is based on an experiment that was never actually conducted."}]}'::jsonb,90,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e1400447-afef-3d25-557f-b9bd52aa1da6','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Text 2 found that more options sometimes reduced choosing and sometimes did not, depending on circumstances. Choice A is incorrect because Text 2 calls the effect inconsistent. Choice C is incorrect because Text 2 says more options \"often\" had no effect or increased satisfaction, not that they always did, and it acknowledges cases of reduced choosing. Choice D is incorrect because nothing in Text 2 questions whether the jam experiment took place."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('07f979f1-2ebd-38ae-a673-9c34abf577c4','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Which choice best describes how Text 2 relates to Text 1?","passage":"Text 1: Restorers of old paintings once routinely removed darkened varnish and repainted damaged areas so that works would look as they did when new. Today, many conservators avoid such repainting, arguing that it replaces the artist''s work with the restorer''s guesses.\n\nText 2: Leaving damage visible is not a neutral choice either. A painting with large losses can be so distracting that viewers cannot grasp the composition the artist intended. Many conservators therefore fill losses with paint that blends in from a distance but can be detected up close and easily removed.","options":[{"id":"A","label":"Text 2 rejects all of the modern conservation methods described in Text 1."},{"id":"B","label":"Text 2 agrees that damaged areas of paintings should never be filled."},{"id":"C","label":"Text 2 complicates the approach described at the end of Text 1 by describing a compromise between full repainting and leaving damage untouched."},{"id":"D","label":"Text 2 argues that restorers should return to repainting works so they look new."}]}'::jsonb,91,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('07f979f1-2ebd-38ae-a673-9c34abf577c4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 2 notes the cost of leaving damage visible and describes detectable, removable fills as a middle path. Choice A is incorrect because Text 2 describes a method used by \"many conservators\" today. Choice B is incorrect because Text 2 describes conservators filling losses. Choice D is incorrect because the fills described are deliberately detectable and removable, not attempts to make works look new."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6854d829-bcf2-e6e9-8b10-8786e41ba266','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the approach described in Text 1?","passage":"Text 1: Astronomers searching for life beyond Earth have traditionally focused on planets in a star''s \"habitable zone,\" the range of distances at which surface temperatures allow liquid water to exist.\n\nText 2: Some of the most promising places to look for life in our own solar system lie far outside the habitable zone. Several moons of Jupiter and Saturn appear to hold oceans of liquid water beneath icy crusts, kept warm by heat generated as the moons are flexed by their planets'' gravity.","options":[{"id":"A","label":"By arguing that liquid water is not necessary for life"},{"id":"B","label":"By claiming that planets in the habitable zone cannot have liquid water"},{"id":"C","label":"By agreeing that only the habitable zone is worth searching"},{"id":"D","label":"By suggesting that it may overlook places where liquid water exists for reasons other than distance from a star"}]}'::jsonb,92,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6854d829-bcf2-e6e9-8b10-8786e41ba266','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because Text 2 describes moons outside the habitable zone that have liquid water warmed by gravitational flexing, which a distance-based search would miss. Choice A is incorrect because Text 2 treats liquid water as what makes these moons promising. Choice B is incorrect because Text 2 says nothing against habitable-zone planets. Choice C is incorrect because Text 2 points to promising places outside the zone."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('05c67143-8aad-a1f8-3368-27d49d8da0ac','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, the author of Text 2 would most likely argue that the benefit described in Text 1","passage":"Text 1: Some researchers argue that taking notes by hand leads to better learning than typing them. Because writing by hand is slower, students must summarize and rephrase what they hear, and this processing helps them understand and remember the material.\n\nText 2: In one study comparing note-taking methods, the advantage of handwriting shrank or disappeared when students who typed were instructed to summarize lectures in their own words rather than transcribe them word for word.","options":[{"id":"A","label":"depends more on how students take notes than on whether they use a pen or a keyboard."},{"id":"B","label":"is caused by the physical act of holding a pen."},{"id":"C","label":"is greatest when students type lectures word for word."},{"id":"D","label":"has never been observed in any study."}]}'::jsonb,93,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('05c67143-8aad-a1f8-3368-27d49d8da0ac','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because typists who summarized in their own words lost much of the gap, pointing to summarizing rather than the tool as the key factor. Choice B is incorrect because Text 2 suggests the benefit comes from summarizing, not from the pen. Choice C is incorrect because word-for-word typing was the condition in which handwriting retained its advantage. Choice D is incorrect because Text 2 says the advantage \"shrank or disappeared,\" implying it was observed under some conditions."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2c33feb0-9e0e-1816-cb3a-1106beb7c957','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the linguists in Text 2 most likely respond to the critics in Text 1?","passage":"Text 1: Critics often complain that texting and social media are degrading young people''s writing. They point to abbreviations and missing punctuation in online messages as signs of declining skill.\n\nText 2: Linguists who study digital writing find that many young people switch easily between informal online styles and formal written English, adjusting to their audience much as speakers shift between casual and formal speech. Using abbreviations with friends, in this view, no more signals an inability to write formally than slang signals an inability to speak politely.","options":[{"id":"A","label":"By agreeing that abbreviations are evidence of declining writing skill"},{"id":"B","label":"By arguing that informal online writing does not necessarily indicate a lack of formal writing ability"},{"id":"C","label":"By arguing that formal written English should adopt online abbreviations"},{"id":"D","label":"By claiming that slang is a greater problem than abbreviations"}]}'::jsonb,94,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2c33feb0-9e0e-1816-cb3a-1106beb7c957','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because the linguists say young people shift between styles, so abbreviations online do not show an inability to write formally. Choice A is incorrect because the linguists reject that interpretation. Choice C is incorrect because the linguists describe switching between styles, not changing formal English. Choice D is incorrect because slang is used only as an analogy, not judged as a problem."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5c1435e2-c68e-d33d-8952-6f12d5698d00','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the view described in Text 1?","passage":"Text 1: Because no finite set of observations can prove a universal law, some philosophers have argued that science advances not by confirming theories but by trying to refute them. On this view, a theory earns confidence only by surviving rigorous attempts to show that it is false, and a genuine contrary observation should lead scientists to reject it.\n\nText 2: Working scientists rarely abandon a well-established theory at the first contrary observation. More often they question the instrument, the auxiliary assumptions, or the data, and such persistence has sometimes been vindicated: anomalies once taken to threaten a theory were later explained within it.","options":[{"id":"A","label":"By rejecting the idea that observations can ever bear on the evaluation of scientific theories"},{"id":"B","label":"By agreeing that scientists typically abandon a theory as soon as an observation contradicts it"},{"id":"C","label":"By suggesting that the view does not fully capture scientific practice, since a single contrary observation is often not treated as decisive"},{"id":"D","label":"By arguing that universal laws can be proven if enough observations are collected"}]}'::jsonb,95,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5c1435e2-c68e-d33d-8952-6f12d5698d00','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 2 describes scientists questioning data and assumptions instead of rejecting a theory, and notes that this caution has sometimes been justified, which is at odds with the view that a contrary observation should lead to rejection. Choice A is incorrect because Text 2 treats anomalies as important, just not automatically decisive. Choice B is incorrect because Text 2 says scientists rarely do this. Choice D is incorrect because Text 2 does not address proving universal laws."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a4767226-445f-b7fe-3f58-b3d4477bfa1d','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely view the portrayal of guilds in Text 1?","passage":"Text 1: Historians have often portrayed the medieval guild as a cartel. By restricting who could enter a trade and fixing prices, guilds enriched their members at the expense of consumers and discouraged innovation.\n\nText 2: Guilds did restrict entry, but their rules also enforced quality standards that buyers could not easily check for themselves, such as the purity of silver or the soundness of woven cloth. In markets where cheating was hard to detect, such enforcement may have made possible trade that would otherwise not have occurred.","options":[{"id":"A","label":"As entirely mistaken, because guilds did not restrict entry into trades"},{"id":"B","label":"As incomplete, because it neglects a function of guilds that may have benefited buyers"},{"id":"C","label":"As accurate, because quality standards mainly served to raise prices"},{"id":"D","label":"As misleading, because guild quality standards were designed mainly to exclude competitors rather than to protect buyers"}]}'::jsonb,96,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a4767226-445f-b7fe-3f58-b3d4477bfa1d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Choice B is the best answer because Text 2 accepts that guilds restricted entry but adds that their quality enforcement may have helped buyers trust the market. Choice A is incorrect because Text 2 explicitly says guilds \"did restrict entry.\" Choice C is incorrect because Text 2 presents quality standards as protecting buyers, not as a way to raise prices. Choice D is incorrect because Text 2 presents quality enforcement as something that may have protected buyers and made trade possible, not as a disguised way of excluding competitors."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a24c87ab-8895-9ae8-d1c6-399004556db5','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the claim in Text 1?","passage":"Text 1: Biographical criticism holds that knowing the circumstances of an author''s life can illuminate the work. A poem written in the months after a bereavement, for instance, reads differently once we know of the loss, and details that seemed obscure may suddenly make sense.\n\nText 2: The difficulty is that biography can close off interpretation as easily as it opens it. Once readers learn of a bereavement, they tend to read every dark image as grief, overlooking passages that resist that reading, and the poem shrinks to fit the life.","options":[{"id":"A","label":"By denying that knowledge of an author''s life affects how readers interpret a work"},{"id":"B","label":"By arguing that poems written after a bereavement rarely contain dark images"},{"id":"C","label":"By suggesting that readers should consult an author''s biography only after interpreting a work independently"},{"id":"D","label":"By conceding that biographical knowledge changes how a work is read while warning that the change can narrow interpretation"}]}'::jsonb,97,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a24c87ab-8895-9ae8-d1c6-399004556db5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Choice D is the best answer because Text 2 accepts that knowing about a loss affects reading, since readers then see grief everywhere, but argues that this can make the poem \"shrink to fit the life.\" Choice A is incorrect because Text 2''s argument depends on biography affecting interpretation. Choice B is incorrect because Text 2 assumes such poems contain dark images that readers interpret as grief. Choice C is incorrect because Text 2 identifies a risk of biographical reading but proposes no remedy, such as a particular order for reading the work and the biography."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('58e7d1df-ddc7-64a4-d526-a45f32b011fe','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the reasoning described in Text 1?","passage":"Text 1: Studies of identical and fraternal twins suggest that genetic differences account for roughly half of the variation in many personality traits. Researchers reach this estimate because identical twins, who share nearly all their genes, resemble each other more closely than fraternal twins, who share about half.\n\nText 2: Twin studies rest on the assumption that identical and fraternal twins grow up in equally similar environments. If identical twins are treated more alike—dressed alike, placed in the same classes, mistaken for each other—then some of their greater resemblance could reflect shared experience rather than shared genes.","options":[{"id":"A","label":"By suggesting that the estimate of genetic influence could be too high if a key assumption does not hold"},{"id":"B","label":"By arguing that identical twins do not actually resemble each other more than fraternal twins do"},{"id":"C","label":"By suggesting that the estimate of genetic influence cannot be evaluated without studying twins raised apart"},{"id":"D","label":"By agreeing that the estimate of genetic influence is probably too low"}]}'::jsonb,98,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('58e7d1df-ddc7-64a4-d526-a45f32b011fe','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 2 argues that if identical twins share more similar environments, part of their extra resemblance would be credited to genes wrongly, inflating the estimate. Choice B is incorrect because Text 2 accepts the greater resemblance and questions only its cause. Choice C is incorrect because Text 2 questions an assumption behind the estimate but does not say what kind of study would be needed to evaluate it. Choice D is incorrect because Text 2''s concern points toward an overestimate, not an underestimate."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b65daaa8-10d9-2971-5357-f1084b25a740','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, how would the author of Text 2 most likely respond to the reasoning in Text 1?","passage":"Text 1: Archaeologists long interpreted the massive earthen mounds built by some ancient societies as evidence of powerful rulers who could command large workforces. Monuments on such a scale, they reasoned, could only have been built under centralized authority.\n\nText 2: At several sites, excavations suggest that mounds grew through many small episodes of construction spread over generations, with remains of feasts accompanying each addition. Such evidence points to communal gatherings, in which groups joined voluntarily in periodic labor, rather than to a ruler''s command.","options":[{"id":"A","label":"By denying that the mounds required a large total amount of labor to build"},{"id":"B","label":"By claiming that feasting, rather than building, was the main purpose of the mounds"},{"id":"C","label":"By arguing that the scale of a monument does not by itself show centralized authority, since it could result from repeated voluntary efforts"},{"id":"D","label":"By agreeing that only powerful rulers could have organized construction on such a scale"}]}'::jsonb,99,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-024","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b65daaa8-10d9-2971-5357-f1084b25a740','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Choice C is the best answer because Text 2 shows that large mounds could accumulate through many small, voluntary efforts, undercutting the inference from size to centralized power. Choice A is incorrect because Text 2 does not deny the total labor; it argues that the labor was spread across generations. Choice B is incorrect because Text 2 presents feasts as accompanying construction, not as the mounds'' main purpose. Choice D is incorrect because Text 2 offers an alternative to rulers'' command."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a470deb9-5626-9d4f-57b1-272c19d60d57','acc30d55-7639-3440-ab2d-92d11a811f7b','question_single_choice','{"prompt":"Based on the texts, the author of Text 2 would most likely argue that the evidence cited in Text 1","passage":"Text 1: Some linguists hold that the language people speak shapes how they think. They cite speakers of languages that describe locations using cardinal directions (for example, \"the cup is north of the plate\"), who keep track of their orientation remarkably well, even in unfamiliar places.\n\nText 2: Such correlations are difficult to interpret. Communities whose languages rely on cardinal directions may live in landscapes where keeping track of direction is practically important. The same environmental demands could produce both the linguistic habit and the navigational skill, without the language itself causing the skill.","options":[{"id":"A","label":"is consistent with an explanation in which language does not cause the observed skill."},{"id":"B","label":"shows that language has no effect on thought."},{"id":"C","label":"proves that environment shapes language more than it shapes thought."},{"id":"D","label":"contradicts the claim that these speakers keep track of direction well."}]}'::jsonb,100,'{"section_type":"reading_writing","sat_domain":"vocabulary_in_context","sat_official_domain":"craft_and_structure","sat_skill":"cross_text_connections","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"cs-ctc-025","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a470deb9-5626-9d4f-57b1-272c19d60d57','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Choice A is the best answer because Text 2 proposes that the environment could produce both the language habit and the skill, so the evidence fits a non-causal explanation. Choice B is incorrect because Text 2 says only that the evidence is hard to interpret, not that language has no effect. Choice C is incorrect because Text 2 offers a possibility, not proof. Choice D is incorrect because Text 2 accepts that the speakers have this skill."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
